		{
			"ARENA_RULE_TEXT_1",
			"Your current rank at No.%s at Top Floor, maintain this rank(No.%s to No.%s), the reward is"
		},
		{
			"ARENA_RULE_TEXT_2",
			"Your Highest Rank in History:"
		},
		{
			"ARENA_RULE_TEXT_3",
			"Battle of Top Floor Rules:"
		},
		{
			"ARENA_RULE_TEXT_4",
			"1.Reward will be sent via mail after 9 pm every night based on rank.|2.Battle of Top Floor is in auto mode and can't switch to manual.|3.All Battle Girls' HP and heal effect will be increased with a fixed amount.|4.If the challenger wins against the defender, their rank will be switched if the defender has higher rank than the challenger.|5.When battles are timeout,the one side with more living units will win,if the living units are the same,the side dealt more damage will win.|6. Players have 5 times to join for free daily,and will be reset at 5:00 everyday.|7.Each battle has 10 minutes CD times.|8.21:00-21:30(GMT+8) will be the calculation time to avoid the problems of masters being sniped after 21:00 or so. Masters cannot initiate any challenge during the period."
		},
		{
			"ARENA_RULE_TEXT_5",
			"History Highest Rank Reward Rules:"
		},
		{
			"ARENA_RULE_TEXT_6",
			"Each time when you reach the highest rank in history, we will send you diamonds for reward.|Reward is based on rate of progress, at least 1 diamond for each time.|Reward will be issued via mail."
		},
		{
			"ARENA_RULE_TEXT_7",
			"Rules of Daily Rank Reward:"
		},
		{
			"ARENA_RULE_TEXT_8",
			"Reward is based on daily rank and issued via mail, here are details:"
		},
		{
			"ARENA_RULE_ITEM_TITLE_1",
			"Top.%d"
		},
		{
			"ARENA_RULE_ITEM_TITLE_2",
			"No.%d - No.%d"
		},
		{
			"PEAK_ARENA_RULE_TEXT_1",
			"Your current rank at No.%d at 1 on 1, maintain this rank(No.%d to No.%d), the reward is"
		},
		{
			"PEAK_ARENA_RULE_TEXT_3",
			"Rules of 1 on 1"
		},
		{
			"PEAK_ARENA_RULE_TEXT_4",
			"1. The server rank rewards will be issued at 22:00(GMT+8) on Wednesdays and Sundays. Your scores and rank will not reset after the rewards are sent.The title rewards will be sent based on your Server Rank.|2.1 on 1 battles are automatic, players don't need to control.|3.In 1 on 1, all girls' HP and healing effects will be adjusted accordingly.|4.Players can adjust your formations anytime you want, Junior Group(Below rank 5001) need to set 3 teams, Senior Group(Rank 501-5000) need to set 5 teams, Master Group(Rank 1-500) need to set teams, every team needs at least 1 girl.|5.Junior Group uses Best of 3 to decide the winner, while Senior Group takes best of 5, and Master Group takes best of 7.|6.Defeating all enemy girls will win you the match.|7.When there is a timeout battle, the one with more alive girls will win.|8.When the alive units in both teams are same, the one dealt more damage wins.|9.When the damage is same, defender wins.|10.Junior Group uses scores to place your rank, while Senior and Master Group use rank system.|11.The winner in Junior Group wins scores after defeating opponent, the loser will lose certain scores. In Senior Group and Master Group, the winner and loser will have their rank swapped.|12.In Junior Group, the scores winner gets varies due to the score difference between loser and winner, the bigger the difference, the more scores the winner gains and the more scores the loser loses.|13.Every player can challenge 10 times for free in 1 day, the chances will reset at everyday's 5:00am(GMT+8)|14.After every challenge, you'll have to cooldown for a moment before you can start another challenge. The cooldown time in Junior Group is 1 minute. While the cooldown time is 5 minutes in Senior Group and Master Group.|15.Players in Master Group will have their last 3 teams hidden, Senior Group will have 2 though Junior Group will have none.|16.There are 3 levels in Junior Group.Junior 3 and Junior 2's promotion require players to reach the \"Promotional Score\". From Junior 1 to Senior and Senior to Master, players need to join \"Promotion\".|17.For rules of \"Promotion\", keep reading."
		},
