		{
			"borrow_rule",
			"1.Any girl or pet can be lent out,but not any can be hired::2.Guild will pay you coins which become more as the lending time increases::3.After lending out,girls or pets require at least 30 minutes to be taken back::4. Guild members need to pay coins for borrowing the lend girls or pets::5. Only 1 girl or 1 pet can be borrowed from the same guild member every day::6. Girls or pets with higher academy level than yours can’t be borrowed::7. The salary is paid according to the power of each girl and pet of yours::8. Part of the coins from borrowers will be submitted to your guild,the reset goes to lenders::9. Higher VIP level can lend more girls::10. Girls can be borrowed in campaign,champion,quiz and challenge::11. Each battle allows only 1 girl and 1 pet to be borrowed,and doesn’t return the fees whether you win or lose::12. Same girl can’t fight together::13. In champion,you can only borrow 1 girl who will help you till the end::14. Girls in the workplace can’t be lent,nor can lend girls be deployed in workplace::15. 2 stars will be rated at most for Victory while you borrow a girl in campaign,quiz and challenge::16. You can borrow 1 level higher than your academy level when you are VIP3,the higher VIP level is,the higher level of girls you can borrow.But the girls you borrowed can only higher than your academy level at most 5 levels. "
		},
