		{
			"RULE_DRINK",
			"1.You may only enjoy once on each kind of afternoon tea daily.@2.Afternoon tea is used to recover stamina, different beverages recover different amount of stamina.@3.Beer is free to enjoy, no time or quantity limit.@4.Cocktail and Wine can be bought with coins and diamonds.@5.You can treat guild mates with 5 glasses of drink, which are available for all guild members, first come, first service.@6.Player who buys the first round of cocktail and wine on each day, will be rewarded additional stamina.@7.Cocktail and Wine will be expired in 120 minutes. If repeatedly treated, then remaining time and quantity will be reset.@8.If there are more than 3k cups of cocktail, Guild leader can exchange extra cocktail to guild active points.@9.Every cocktail can be exchanged to 15 guild active points, and 1000 maximum can be exchanged daily.@10.After exchange, the quantity and remaining time of cocktail will be reduced based on how many cocktail you exchange."
