		{
			"team_rule",
			"1.From Chapter7 on, every chapter is an independent Guild Campaign.|2.Opening each Guild Campaign costs a certain amount of Guild Active Points.|3.Leader and vice leaders may reset the Guild Campaign. Resetting it costs the same amount of Guild Active Points.|4.Guild Members can challenge the same mission in each chapter one by one, enemies HP will not regenerate.|5.Each member has 2 chances of missions in each chapter per day to challenge. The chance will be considered as used if you have the mission stage cleared. And the battle time will not reset when you face a new wave of enemies.|6.To not affect other members’ experience, players have to finish formation selection within 1 minute, the battle time must be within 3 minutes.|7.Players can’t join Guild Campaign from 5:00am to 8:00am everyday in server timezone GMT+8.|8.Challenging Guild Campaign will allow you to finish a daily quest which rewards you certain amount of Guild Badges. You may use Guild Badges to exchange items in Guild Exchange.|9.When there is a Guild Campaign cleared, all members will be rewarded with Guild Badge, masters will get bonus Guild Badges if your guild clears the Campaign within 7 days.|10.Guild Campaign records the highest damage dealt by all members, players who positioned highly in this ranking will get bonus Guild Coin.|11.The player who takes the last strike that kills the Guild Campaign Boss also gets bonus Guild Coin.|12.When every battle ends, Guild will reward challengers with gold based on the damage dealt.|13.When calculating the damage, the HP of Boss will be counted double.|14.When Guild Campaign is reset or cleared, a certain amount of Guild Coin will be sent to all members who joined the clearance of this campaign based on the progress your Guild has made through. Guild Coin can be used to exchange gears in “Trophy” store .|15.The damage rank of player will decide how much bonus Guild Coin you can get.|16.If the Guild Campaign is cleared within 7 days. The basic Guild Coin reward will be improved.|17.When Guild Campaign resets, it will register all current members in Guild. The unregistered ones will not be able to join Guild Campaign, nor obtain the rewards of this Guild Campaign.|18. Guild Campaign Boss is immune to position swapping skills, but not to the damage of this kind of skill. Maidam's ultimate is an exception. Some girls’ skills may not sneak behind the Boss like Smartie, Guan Yin and Androi."
		},
