		{
			"REGION_ARENA_RULE2",
			"Rules"
		},
		{
			"REGION_ARENA_RULE3",
			"About the reward pack for LV15: |Pvp Skin Pack: Open it and then you can select a reward from: Valiance-Huni, Charm Summer-Handana, Moon Vows-Luna, Instant Firework-Hanzo, Cat Maid-Kitty, Soul Saw-Chainsaw, Hip-Hop Lead Singer-Elina, Fireman-Sasuke, Monster-Vanees, Baseball Catcher-Nancy, Sword Ambition-Okita.| 1.Arena is Season Mode, each season has 45 days.|2.Each Season has 26 levels, from LV1 to LV.MAX Lord.|3.Each victory earns 1 Gem, before LV20,you may earn 2 gems for each victory after having a 4 times win-streak.|4,You will be promoted when Gems are fully earned.|5,LV6 and above will lose 1 Gem if you lose the battle till you have 1 Gem left, level will be lowered if lose again in this status.|6.LV.MAX will not be lowered and you can start to earn Lord Points.|7.LV.MAX earns more Lord Points when defeating high ranked opponents.|8.LV15 will earn Participation Rewards when Season is over.|9,LV.MAX will earn Lord Rewards when season ends.|10,Rank 1 player will earn Champion Rewards, which includes the Champion Portrait .Champion Portrait will last for 45 days.|11,Season Rewards will be distributed via mail.|12,Extra Arena coins will be issued by first 10 challenges daily.|13.Practice mode counts no rewards or punishment.|14.Successfully defend 3 challenges consecutively earns you 1 Gem. Fail to defend 3 challenges consecutively loses 3 Gems of yours.|15.Timeout battles will count the side with more living girls win.If the living units of both sides equal, the side who dealt more damage wins.|16.Notice about the balancing in Arena：|By Player=Match according to your current situation.|Top to same lv=When your level is not enough, you will be promoted to a certain level; If your level is beyond it, we will match you according to your current situation. No effect=It will not work in this mode.|Following are the details for balancing：|Girl's Skin:By Player|Girl's Level:Top to same lv|Girl's Awaken:By Player|Girl's Skill:Top to same lv|Girl's Gear:Top to same lv|Girl's Star:By Player|Emblem:No effect|Enchant:No effect|Bookshelf in Workshop:No effect|Purify:No effect|Apartment:By Player|Subject Selection:No effect|Breakout:By Player|Elemental Gear:By Player|Pet's Level:Top to same lv|Pet's Skill:Top to same lv|Pet's Star:By Player|Pet's Awaken:By Player|Pet's Gear:Top to same lv|Engaged Girl's Star:By Player|Engaged Girl's Gear:By Player|Engaged Girl's Level:By Player|Engaged Girl's Skill:By Player|Engaged Girl's Skin:By Player|We will update the rules for balancing according to the our game's progress at regular time!"
		},
