		{
			"KITE_KING_RULE",
			"1.During event, you can get kites by recharging required amount of diamonds. |2. Your one-time recharge must reach the requirements to get kites, if you recharge more than 3000 diamonds at a time, it’ll be counted as 3000 diamonds recharge. |3.You will get the kites from other 2 options if your one time recharge reaches 3000 diamonds. Which means, recharging 600 diamonds will also earn you 300 diamonds level of rewards.|4.After flying a kite, other players are needed to find the kite in correct location to earn diamond rewards. Getting the wrong place will result in you getting less diamond rewards! |5.To join the Election, you must be above lv20 and at least fly 10 kites during event. |6.During event, you can join the Election any time as long as you fit the requirement. |7.The rank in Election will be displayed by the votes participant gets. Rank 51 and below will not be displayed|8.Every player can vote for 1 player once a day, the vote of first 4 days will reward you gold, and the last 3 days will earn you diamonds. The more votes you send, the more rewards you get. |9.Except winning votes from players, you can get votes through flying kites. |10.Every vote players send you equals to 2 votes, flying 1 mini kite equals to 1 vote, flying 1 classic kite equals to 2 votes, flying 1 deluxe kite equals to 10 votes. |11.The event will start calculating rewards on the last day of event at 22:00(GMT+8). Players will receive their rewards based on their rank via email.|12. The No.1 player will receive 1 additional reward which is called \"Event Ticket\". The user may use \"Event Ticket\" to open 1 ordinary event for all servers that lasts for 6 hours."
		},
