			"BEACH_RULE",
			"Rules of Beach Carnival: |1.1 free chance for every player daily during event.|2.10 free attack times after you enter this event for the first time (Attack times can also be purchased with diamonds). Every time you attack Boss, will consume 1 attack time (Critical Attack also will deduct 1 attack time).|3.Once enter, there are 3 different kinds to attack: Pink Octopus, Blue Octopus and Red Octopus; Pink Octopus will create 1 damage, Blue Octopus 3 damages, Red Octopus 5 damages.|4.When player initiates the Critical state, the damage will be tripled.|5. Players can only connect same Octopuses adjacent to each other on a straight line or diagonal line. The more Octopuses linked, the more damage will be created.|6.Players can click to open the treasure chest after defeat Boss. The boxes contain Octagirl Scroll, SX Juice，Raid Ticket, and Dragon Manual. The higher boss the more rewards.|7. Players can unlock Adv Rewards after purchasing \"Octopus Pack\". There will be advance rewards and skins. |8. There is a chance limit everyday! Think twice before quitting the mission, Click Reward to check. "
