		{
			"REGION_MISSION_RULE",
			"1、競技模式為賽季制度，每個賽季持續45天。|2、在每個跨服競技賽有26個等級，從LV.1晉級到LV.MAX王者。|3、每次勝利獲得一顆寶石，低於20級時連勝4次及以上獲得2顆寶石|4、寶石數滿了即可晉級為下一級。|5、當升至LV.16後對戰失敗會降低一顆寶石，直到降級為LV.15。若戰鬥超時則算作進攻方失敗|6、當升至LV.MAX時失敗將不會再降級，開始計算王者積分|7、在LV.MAX王者戰勝的對手越強，獲得的王者積分越多。|8、賽季結束後，戰績等級達到LV.15會獲得參與獎。|9、賽季結束後，戰績等級達到LV.MAX會獲得王者獎勵。|10、賽季結束後，排行榜第一名的玩家會獲得冠軍獎勵，頭像持續時間為45天，到期將自動消失。|11、賽季獎勵以郵件形式發放。|12、每天前10次匹配無論勝負都會獲得額外跨服幣獎勵。|13、練習模式沒有勝利獎勵與失敗懲罰。|14、連續防守勝利3次將獲得一顆寶石，連續防守失敗3次將扣除一顆寶石。|15、已召喚的所有戰姬、寵物的等級和品階將被拉平到90等橙色+2滿裝備滿附魔狀態。|16、保留戰姬、寵物的星級和覺醒狀態。"
		},
		{
			"ANNIVERSARY_THIEF_RULE_TITLE",
			"Rules of Witch's Trick"
		},
		{
			"ANNIVERSARY_THIEF_RULE_TEXT",
			"Here comes Halloween again, masters! Witch has been preparing for such a moment, but she needs you all to challenge her to get your rewards. Or her preparations will be in vain.|1.During the event, every player has 3 chances to challenge Witch per day.|2.Only your highest damage record in 1 day will be counted into total damage rank.|3.Every time you done challenging Witch, you'll get some rewards she has prepared.|4.The top 50 players on the damage ranking toward Witch will be additionally rewarded.|5.The total damage will be calculated at 22:00 of server time everday during event.|6.Witch has spells to make herself immune to all kinds of controlling skills but she still can get poisoned, defense reduced or some other debuffs."
		},
		{
			"ANNIVERSARY_JIGSAW_RULE_TITLE",
			"Rules of Mystic Puzzle"
		},
		{
			"ANNIVERSARY_JIGSAW_RULE_TEXT",
			"1.During Mystic puzzle event, collect pieces of puzzle by clearing various missions When reach certain level, you will be rewarded!|2.Click every piece of puzzle, then you will find out detailed method to acquire. |3.Every time you acquire a new piece, drag it to the correct place, then you will have your rewards. |4.Find the hidden words in puzzle, you will be rewarded with special bonus."
		},
