			"ANNIVERSARY_GACHA_RULE_TITLE",
			"Rules of Capsule Toy"
		},
		{
			"ANNIVERSARY_GACHA_RULE_TEXT",
			"1.During event, masters may roll the stick of Gashapon machine with Gashapon coins. |2.Obtainable rewards in Gashapon machine can be viewed in \"Collection\", different rewards have different rarity, get the rare rewards as much as you can! |3.Every day's 1st login and obtaining 150 daily quest active medals will both reward you 1 Gashapon coin. |4.During event, every 300 diamonds recharge will earn you 1 Gashapon coin, 600 diamonds recharge will earn you 2 and so forth. |5.The separate recharges will not be accumulated. For instance, if you recharge 400 diamonds and 200 diamonds separately, you will only earn 1 Gashapon coin. |6.When the animation of rolling rewards is playing, you may click the stick again to skip it. |7.After event ends, the unused Gashapon coins will be deleted, do note to use them all during the event!|8.Now capsule toy has a guaranteed Rarest Reward for you if you didn't get a Rarest Reward with 30 pulls. The reward will be 1 rarest reward from all of them."
		},
		{
			"ANNIVERSARY_CAKE_RULE_TITLE",
			"Rules of GXB Thanksgiving Cake"
		},
		{
			"ANNIVERSARY_CAKE_RULE_TEXT",
			"1.During the GXB Thanksgiving event, you can enjoy the cake by logging in the game once everyday. |2.You will be presented certain items after eating the cakes.|3. The cake will expire the next day if you don't eat it.|4. During event, time for login is reset every 5:00 am, so don’t forget to eat it before 4:59 am."
		},
		{
			"ANNIVERSARY_CANDLE_RULE_TITLE",
			"Rules of Wishing Candle"
		},
		{
			"ANNIVERSARY_CANDLE_RULE_TEXT",
			"1.During Rooster Year events, you can unlock your ideal event by igniting the wishing candle represents that event. |2. The wishing candles can be acquired by defeating the angry chicken, meanwhile, you can also use diamonds to make your wish directly. |3. The event wished by most players will be started at 5:00 am the next day. |4. The wished event will be held for 3 days."
		},
