		{
			"INCUBUS_RULE",
			"1.Only lv90 and above players can join Guardian.|2.There can only be 5 girls on the battlefield at the same time.|3.There will be random quests during the battle，completing or failing will result in bonus buff or debuff for your team. |4.Players can join Guardian 3 times everyday，VIP players can use diamonds to purchase attempts. |5.Girls’ HP will drop due to the attacks from thugs. The clearance of enemies in each wave will recover some HP for girls. The battle ends when girls’ HP drops to 0. |6、Defeating the thugs might randomly drop scrolls of the target girl you guarded and dots of some rare gears. |7.Guardian consumes your stamina, the sequence of stamina consumption for guarding each girl is this: 1st time joining consumes 30 stamina, 2nd time joining consumes 60 stamina, 3rd time joining consumes 90 stamina, 4th time joining consumes 120 stamina and then it will stay at 120 stamina consumption for further challenges.|8.To enter the battle, you have to select a 5 girls- starter team and they will definitely show up in the available units.|9、After the selection of starter team，you can choose the support units，support units will automatically join the available units with the time passes.|10.Support units will randomly join the available units.|11.Deploying girls to battle field costs energy，energy will slowly increase with time passes. |12.There are some girls always busy with their practices so that they will not join this heroic action.|13. The scary atmosphere causes girls in battle field to keep losing HP. |14.The more girls there are in the battle field, the higher the energy cost will be for next girl's deployment.|15.If you quit guardian in the middle way, you will lose 5 stamina as a punishment but all the items gained will disappear. |16.After you finish the Guardian of any girl, you may use raid tickets to raid that challenge, the raid ticket will only reach the highest record you done manually. |17.When you raid in Guardian，1 wave clearance consumes 1 raid ticket you have. You can use diamonds to continue the raid if you don't have enough raid tickets."
