		{
			"PLAYOFF_RULE_TEXT1",
			"Rules of Arena Playoffs Registration:"
		},
		{
			"PLAYOFF_RULE_TEXT2",
			"1.After current season ends, the top 50 players on Arena ranking can start registration and the top 32 players in the ranking who also registered playoffs will be chosen as contenders. |2.Any contender who is found out cheating will receive the removal of his qualification joining Playoffs as punishment."
		},
		{
			"PLAYOFF_RULE_TEXT3",
			"Rules of Arena Playoffs Matching:"
		},
		{
			"PLAYOFF_RULE_TEXT4",
			"1.Playoffs is consisted of 5 stages:Qualifying Match.Round 16.Quarter-Final.Semi-Final.Final.|2.During Qualifying Match,all 32 contenders will be randomly divided into 8 teams.Each team contains 4 contenders and each contender will compete with other 3 in the team one by one.|3.The battle mode is best of 3 in Qualifying Match.|4.Round 16:The 2 contenders have most wins in one team will be chosen for Round 16.Registration sequence will decide the qualification for Round 16 when the wins are same.|5.Round 16 will go with this sequence:No.1 in Team A fights No.2 in Team B,No.1 in Team B fights No.2 in Team A,and so on.|6.Quarter-Final:8 winners will be divided into 2 teams,deciding 4 winners with Best of 3 mode.|7.Semi-Final:4 winners will be divided into 2 teams deciding Top 2 with Best of 1 Mode.|8.Final:Top 2 will have the final to decide the champion and the 2nd place.Each round has a 20 mins time interval|9.Every match is held during a certain time,contenders are required to stay online and join the match in Arena page during that time.|10.Battle will start automatically if the contender cannot get prepared for the match during the required period.|11.Please participate the match under stable internet connection.|12.Notice about the balancing in Arena：|By Player=Match according to your current situation.|Top to same lv=When your level is not enough, you will be promoted to a certain level; If your level is beyond it, we will match you according to your current situation.No effect=It will not work in this mode.|Following are the details for balancing：|Girl's Skin:By Player|Girl's Level:Top to same lv|Girl's Awaken:By Player|Girl's Skill:Top to same lv|Girl's Gear:Top to same lv|Girl's Star:By Player|Emblem:No effect|Enchant:No effect|Bookshelf in Workshop:No effect|Purify:No effect|Apartment:By Player|Subject Selection:No effect|Breakout:By Player|Elemental Gear:By Player|Pet's Level:Top to same lv|Pet's Skill:Top to same lv|Pet's Star:By Player|Pet's Awaken:By Player|Pet's Gear:Top to same lv|Engaged Girl's Star:By Player|Engaged Girl's Gear:By Player|Engaged Girl's Level:By Player|Engaged Girl's Skill:By Player|Engaged Girl's Skin:By Player|We will update the rules for balancing according to the our game's progress at regular time!"
		},
		{
			"PLAYOFF_RULE_TEXT5",
			"Rules of Arena Playoffs Betting:"
		},
		{
			"PLAYOFF_RULE_TEXT6",
			"1.Players may bet on their favorite contender from the ending of registration to the ending of Playoffs.丨2.Players above lv60 may bet on their favorite contender.|3.You will earn basic rewards if the contender you bet advances in Qualifying Match or wins once in any other match.The higher your academy level,the more your rewards will be.|4.When the contender you bet advances in Round 16.Quarter-Final.Semi-Final.Final,basic rewards for you will be doubled.|5.For example,if player A bets on Contender A,Contender A advanced in Qualifying Match and Round 16 but got wiped out in Quarter-Final.Player A will receive doubled basic rewards.(Earned basic rewards after Contender advanced in Qualifying Match,rewards are doubled after Contender advanced in Round 16.)|6.Every player can get 32 times of basic rewards if he bets(The contender he bets becomes Champion)|7.If the contender you bet gets wiped out,you may continue bet on other advanced contenders.|8.Rewards will be sent out via mail when the Playoffs are over."
		},
		{
			"PLAYOFF_RULE_TEXT7",
			"Rules of Arena Playoffs Reward:"
		},
		{
			"PLAYOFF_RULE_TEXT8",
			"1.Champion player may choose 1 SX from all SX girls that have been released in game and an exclusive frame that symbolizes the champion's glory will be given as well, we'll contact the champion after playoff ends to issue the reward he(or she) wants.|2. 2nd place will earn 5K diamonds,10 million gold as rewards.|3.Semifinalists will earn 2k diamonds,4 million gold as rewards|4.Quarterfinalists will earn 1k diamonds,2 million gold as rewards.|5.Round 16 contenders will earn 500 diamonds,1 million gold as rewards.|6.Qualifying Match contenders will earn 200 diamonds,400k gold as rewards.|7.Every contender can only collect reward once per his best grade."
		},
