			"FIREWORK_RULE_TEXT",
			"1. During the event, you will get different kinds of fireworks after recharge. The numbers of fireworks  are related to recharging diamonds. |2. When the firework appears in the sky, click the button when the firework is blooming to take a picture of the firework. There are 5 free times every day. Every time you use a firework, you will get an extra chance to take a picture. The times will be reset everyday. please don't forget!!!!! |3. You can get the Firework Ticket by using fireworks and takings picture, which can be used to exchange items in fireworks exchange shop of this the event. The Firework Ticket will expire after the event. |4. When using the firework, don't worry about the time is too short for other players to see it. Each fireworks will last for a period of time. Everyone who comes here can see your firework~|5. Whenever a player in the game uses the firework, the Fire Lv. will go up. When it levels up, there will be a reward restoring. After reaching the target Lv., you will get the restoring rewards by mail after event.|6. After reaching Fire Lv. Max level,  masters will no longer receive rewards by using firework.|7.The explore items will expire after the event,so remember to use them in time."
