		{
			"PARADISE_RULE_TITLE",
			""
		},
		{
			"PARADISE_RULE_TEXT",
			"A new park named Fantasy was built upon a clearing near the academy, as people say, by an old friend of principal. But the weirdest part is that how it could be done over one night. Thus girls decided to reveal the truth! Unexpectedly what waited them are dangerous guardian bosses in front of every recreation facility, there must be some secrets about it! |1. You need to be lv.65 or above to challenge bosses in Fantasy. |2. After boss is refreshed, you get 5 free chances to challenge. |3. The damage in rank is your highest damage to a boss. |4. Rewards are calculated every 10 pm(GMT+8) after boss is refreshed, before which Fantasy needs to be closed for 2 minutes. |5. Rewards are sent every 10 pm(GMT+8) according to your highest damage rank on current day. |6. The highest damage to boss of each guild member will be summarized into the guild rankings of Fantasy. |7. Guild active points as rewards are sent every 10 pm(GMT+8) according to the guild rank of total damage. |8. Each time when losing a certain amount of health, the boss stacks a Rage buff. |9. You can borrow battle girls in Fantasy. |10. Fantasy coins rewarded can be exchanged for items in Fantasy’s store. |11. You are also rewarded 20% of your daily highest damage to boss as coins every 10 pm(GMT+8). |12. Boss in Fantasy can be killed. |13. From Fantasy’s daily closing time on, it needs 1 day to be maintained and after that will be reopened at 8 am(GMT+8).|14. The team mode requires 3 players to complete and the team leader must deploy a pet.|15. Team mode will not cost your daily attempts challenging Fantasy|16.In team mode, players cannot deploy girls that have low attack power.|17.The score you get in team mode will be counted as your personal score.|18.You will receive an extra reward based on your Team Mode ranking.|19.Player's ranking will be decided by the damage, if the damage happens to the the same, the shorter time you spent, the higher rank you'll get."
		},
