		{
			"ACTIVITY_SINGLE_RULE_TITLE",
			"Rules of Couple Action"
		},
		{
			"ACTIVITY_SINGLE_RULE_TEXT",
			"1. It needs two players to establish a partnership to participate in this event. Players without a partner can't have goals. You can terminate the partnership during the event, but there will be a punishment.|2. There is a time limit of 24 hours for application. The application will be abolished after the overtime time. In the mean time, only players whose level gap is under 20 levels can be partners.| 3. There are five goals for each day. All the goals need to be completed by both of two partners. After finishing, you could get points. The goals can be assigned by any one of the two partners before they start and can't be changed. The progress will only be recorded after the goals are assigned. Please remember to assign the goals.|4. There will be a special goal - challenge. There will be two different bosses for players to challenge. And two bosses should be assigned to complete respectively. You can get points which are transferred by damage. The challenge can be tried without limit for times before complete. After each challenge, you can choose whether to enter the damage into the final result. After the result is entered, the challenge will be counted as completed.| 5. You can unfriend during the event. The unfriend  application will only last 24 hours. If the partner fails to respond within 24 hours, it will be deemed to agree to termination of the partnership. At the same time, when the unfriend application is rejected once, you can cost the diamond to compulsively delete the partnership.| 6. Once all the goals everyday are completed, you can get the reward. And once all goals of five days are completed, you can get rare frame \"PDA Frame\". After the event ends, you can get abundant rewards according to the rank, please don't miss it. ||【Ranking Rewards】|No1：Winter's Love*1, Dragon Manual*15, Villa Key*1|No2：Winter's Love*1, Dragon Manual*10, House Key*1|No3：Winter's Love*1, Dragon Manual*10, House Key*1|No4 : Winter's Love*1, Dragon Manual*10|No5-No7 : Winter's Love*1, Dragon Manual*8|No8-No10 : Winter's Love*1, Dragon Manual*5|No11-No20 : Winter's Love*1, Spell Book*5|No21-No30 : Winter's Love*1, Spell Book*4|No31-No40 : Winter's Love*1, Spell Book*3|No41-No50 : Winter's Love*1, Spell Book*2|No51-No70 : Winter's Love*1, Spell Book*1|No71-No100 : Winter's Love*1|No101-No200 : Small Juice*15, Spell Book*3|No201-No300 : Small Juice*10, Spell Book*3|No301-No500 : Small Juice*8, Spell Book*3|No501-No700 : Small Juice*5, Spell Book*2|No701-No1000 : Small Juice*5, Spell Book*1"
