		{
			"INSCRIPTION_RULE_TXT",
			"1.When Battle Girls reach lv100 and have finished blood awakening. Emblem system will be unlocked and girls' stats interface will also unlock the medal slots. |2.There are 3 types of medals in game: Specialty Medal, Excellence Medal, Honor Medal. The stats increased by medals vary from their types. What’s more, there are mysterious sets of scholarship medals awaiting masters. |3.Forge different types of medals will cost corresponding amount of star crystal materials. The top-notch medals will additionally cost Heart of Medal. |4.Medals obtained from Forge will gain a random original stat. |5. reforge changes the bonus stats type of medals, but the amount of bonus stats will not be changed; Results of reforge need to be saved manually and Set Medal cannot be reforged. |6.The higher level of the medal, the more stats you can benefit. |7.The higher the level of medals you Forge, the more the materials will be costed. |8.You can only equip the medals in girls’ stats interface. |9.There is a chance to get Scholarship set medals during the reforge and forge of Lv7 medals besides daily quests, while the daily quests will reward you different scholarship medals. Be sure to check it out. And you can only trigger the set stats after equipping a full set.|10.The star of Excellence may craft the medal with following effects: spell damage taken reduction, physical damage taken reduction, lifesteal level, physical crit, spell crit, healing effect, sustained damage, physical crit damage taken reduction, spell crit damage taken reduction, MP regeneration of HP loss. The star of Honor may craft the medal with following effects: spell crit, physical crit, armor ignored, energy regeneration, disability resistance, skill level, MP consumption reduction, silence immunity, physical dodge, spell penetration. The star of Specialty may craft the medal with following effects: max HP, hit rate, HP regeneration, physical attack, spell power, spell resistance, physcial defense, Str, Agi, Int."
