		},
		{
			"TREASURE_RULE_TEXT",
			"1. Masters need to be lv.14 or above to be able to work. More workplaces will be unlocked as your academy level goes higher.|2. You need to spend ice creams for your girls to work. The academy provides 3 ice creams each hour.|3. Different workplaces suits different girls. There is only one place for each girl.|4. Except in Future High-tech Factory, you may meet rivals or gain extra rewards during working in other places. The higher your team’s average attack power, the more chance to beat your opponents.|5. Some girls own a special power that can boost work efficiency, reduce ice cream consumption, or increase the rate to meet rivals or gain extra rewards, etc.|6. Number of your working girls, plus their levels, promotions and stars, will all affect the basic rewards amount.|7. Workplace might offer some work for masters above lv.42 to get bonus diamond rewards after every 5 am.|8.Masters over VIP4 will gain 1.5 times of basic diamonds;masters over VIP7 will gain 2 times of basic and diamonds rewards."
		},
		{
			"CONQUER_SCHOOL_RULE_TITLE",
			"Rules of Conquest"
		},
		{
			"CONQUER_SCHOOL_RULE_TEXT",
			"1. Lv100 players can challenge Conquest. |2.The level icon will be changed once player has passed the first mission in Conquest. |3.The missions you have cleared in Conquest is also a symbol of your ability&strength, and they will be shown in the new level icon. |4.In each mission of Conquest, there will be uncertain numbers of squads or Bosses for you to defeat. |5.When there are many squads as your enemy in one mission, you can challenge them in any sequence you want, but the girls you used in the fight which you successfully defeated the squad will be unusable in this mission. |6.When masters think the rest of your girl may not support you to accomplish the challenge, you may reset the mission and challenge it again. |7.In some missions, there will be random magic casted, which affect both sides on its effect. |8.You have 10 chances to challenge each mission every day, the chance resets at 5:00am of server time every day. |9.Each defeat will grant you 1 encourage buff, stacks up to 10. |10.The 2nd lap of Conquest will unlock when you pass Mission No.56 of the 1st lap. |11. With the lap increased, the opponents will be more powerful. |12.Every time masters pass one lap, you will gain valuable lap passed prize and higher-quality level icon. |13.The permits gained from lap passed prize will play an mysterious role in the future, so please keep them well!"
