		{
			"ACTIVITY_SAKURA2_RULE_TITLE",
			"Rules of Sakura Sightseeing"
		},
		{
			"ACTIVITY_SAKURA2_RULE_TEXT",
			"Another sakura blossom comes! This time, a mysterious girl in a sakura-painted suit shows up in academy, it seems that she is looking for something. And you, who also join this sightseeing, will have a chance to meet her? Would you help her to find what she is looking for? The story begins here--||1. During event, players can obtain『Rice』by clearing normal or elite campaigns, obtain 『Bean-Paste』by drawing vending machine(Exclude cheap ticket; cheap coupon; vip tickets and vip coupon.), obtain『Sakura』in champion.|2. In Dessert Bar, you can mix at least 2 ingredients to make snacks.|3.In Sakura Sightseeing, you may use the snacks you prepared to start your picnic. With different food, different things might happen and you will have a chance to gain different rewards even the mysterious girl’s scrolls—Her favorite snack is 『Sakura Cookie』! But being defeated will grant you no reward. |4.In Sakura War, there will be a story for you to explore and you will learn how twisting the mysterious girl’s background is. You may also obtain her exclusive avatar and a special frame. Limited edition battle girl『Sakura』has double HP, physical attack and spell power in Sakura War, meanwhile, her guide Blowie and Quinie will both gain 50% HP, physical attack and spell power bonus in Sakura War."
		},
