		{
			"TEACHER_RULE_TITLE",
			"Guide for My Class"
		},
		{
			"TEACHER_RULE",
			"The class has begun! Time to find your ideal student and mentor! |1. This function does not apply cross server. 1 mentor can only have 1 student and 1 student also can only have 1 mentor. If you have reached the requirement, you can be mentor and student at the same time, but you can’t have these 2 relationships with 1 same person. |2.Requirement to be student: Academy level is more than 10 and below 90, has no mentor. |Requirement to be mentor: Academy level is more than 60, mentor must be 3 levels higher than student. Has no student. |3.You may send request to 3 different players everyday, request will expire after 48 hours. |4.When you are in a class, you’ll automatically add your mentor/student into friendlist. Thus you 2 can start sending gifts to each other. Not only can you 2 both get friend coins, but also the “Bond” between you 2 will be increased by 100, once a day. The cap of bond is 3000. When you 2 have 1000 bond, 1 stamina gets 0.5 bonus exp; when you 2 have 2000 bond, 1 stamina gets 0.75 bonus exp. When you 2 have 3000 bond, 1 stamina gets the student 1 bonus exp. |5.As a mentor, you can check your target in homework, when your student finish the target, you'll get the corresponding reward. As a student, you can check your target in campus, to finish it, you 'll get the reward|6.When outstanding students finish the quest in Campus. Corresponding amount of scholarship will be given to them. Detailed info can be viewed in Campus. |7.When one side raises dismissal of the relationship, the relationship will immediately be removed. But the raiser will receive punishment of suspending class for 24 hours. And the other side will receive no punishment. But you can’t raise dismissal of a relationship shorter than 24 hours. Bond will be reset to 0 after the relationship is removed. |8.When student reaches lv90. Graduation Test will start, passing it will reward the student and graduation will be approved. The student and mentor relationship will automatically be removed."
		},
