			"Awww, no. Girls in academy just ran into a big trouble, they lost their photos on their way back academy, please help them find those photos back! |1.Battle Girl’s portrait marks the place where they lost their album, click that portrait and masters may start searching. |2.Different girls will reward you differently if you find their albums. |3.After you enter the area, you might encounter other fellow masters who will compete with you, competing with them will cost your stamina, the attack power of fellow masters rise as the floors get higher, which will cost you more stamina while the rewards will be better. |4.Defeating other masters will earn you the keys to open memory album, the keys can be used to open same color album and you must use keys to open it. |5. Every page has a strongest master to guard the gate, and after defeating that master, you’ll be able to access next page. |6.After clearing at least 3 pages, you will gain bonus rewards, so keep trying! |7.If you give up this recall, you can select other girls to help. There is no limit of tries you can do everyday. |8.Click return and you may return to main interface, reentering it will let you continue where you left last time. |9.The defeated Battle Girls cannot attend battles in that round of exploration, but you can choose to revive her with a high cost. "
