		{
			"ZHUGE_RULE_TITLE",
			"Rules for KongMing's Forest"
		},
		{
			"ZHUGE_RULE_CONTENT",
			"Who is that 『KongMing』girl the mysterious man has been talking about? The team led by you who accepted the great mission set on the adventure. Hope your team can reveal it... ||【Exploration Preparations】|1. Before the exploration, you can select 『15 girls and 3 pets』 for your team. |2. If you don't have enough girls or they are not powerful enough, you may spend diamonds to hire girls that you don't have. |3. All girls will be adjusted to lv100 and red+1 in exploration! |4. If there are girls who have 『Leadership』 leader skill in your team, you will be allowed to select several more girls to join the exploration. ||【Notes in Exploration】|1.If you think this forest exploration is difficult, you could spend diamonds to 『skip』. Then your default stamina cost will be defult stamina.|2. After the exploration begins, you can select any area in the map to enter the forest. When you are in the forest, you can only click nearby areas for your team to explore. |3. Every area you enter will trigger a random event, let's see what’ll be waiting for you. |4. When you are exploring the forest, the map of forest will change all the time due to the influence of unknown magic, so be careful. |5. The original stamina in forest is 30. You could use 『Picnic Box』 to regenerate 20 stamina. Every area which you need to explore will cost you 1 to 10 stamina. Every time you move between areas, it will cost you 1 stamina. |6. You can fill your stamina with diamonds.For every 200diamonds recharge, you can get a picnic box. |7. Some girls have special skills that are useful in exploration, girls who have a “lightning” mark on their portraits have this kind of skill. You may tap and hold on their portraits to view the details. ||【After Exploration】|1. The first time you pass through KongMing's Forest will unlock new functions and stories. The 『Cube Material』 you obtained will be a very useful item when you meet her, so get it as many as possible. |2. Besides, a Free Exploration will be unlocked, your girls may enter the forest by themselves and complete the adventure!|3. Before the Free Exploration, you can click the 『adjust』 to reduce the stamina cost with diamonds. ||【Unlock Cube】|1.After Exploration,use Cube Material and you will get great rewards including KongMing！|2.The system will unlock white cube Ⅱ when you have 3-star KongMing.|3.You can get 『Azure Shard』 from black cube. ||【Teleport & Shop】|1.After Exploration, you can go challenge in Teleport which will consume『Azure Shard』.|2.After you finish Teleport, you will get a great mysterious reward and the system will unlock Shop for you. |3.You can get many rewards with『Azure Shard』."
		},
