		{
			"SUMMER_QUIZ_RULE_TEXT",
			"On the biggest stage of our Mid-summer event, the curtains are closed-waiting for a significant event to begin!! |1.During event, the game “Wipeout or Keep On” will begin at GMT(8)12:00-13:00 everyday. Masters who want to join this event, please make sure you will enter the event page in advance. |2.In “Wipeout or Keep On” event, you’ll face wisdom test—Problem Answering and courage test—Defeating Robots. You’ll be approved of passing the test after successfully resolving 20 missions. After you are approved, the time you spent from GMT(8)12:00 till the time you passed the test will be your grades to compete with others. It’ll decide the rewards and rank of yours. |3.If you answered it wrongly, you’ll receive a punishment that makes you unable to answer any question in few seconds. You may choose to wait for it to end or spend diamonds to skip it. |4.In the courage test of defeating robots, all girls will be equalized to lv100 and Red+1. Robots will not attack you though only certain girls can damage them. Read carefully of the notice before you start the test."
