		{
			"AUCTION_RULES",
			"Because of the fierce battles that happened in academy, the head of academy needs a lot of funds to repair the broken places. Thus, many girls have donated their treasures to host this Auction. Hopefully they can gather enough money in days! Masters, time to show your love to girls! |1.Auction is only available from 5:00-21:30(GMT+8) everyday. If you enter the auction after 21:30(GMT+8), you can only view the items that are for auctions on that day instead of being able to join the auction. The items that’ll be in auction will refresh at everyday’s 5:00am. |2.There is only 1 kind of Auction for now-Global Auction, that all players from all servers can join. The bid increment cannot be less than 1% of current highest price. |3.Refreshing button allows you to check the current highest price, so do not forget to refresh before you take your bid! If your price is outbid by others, go to claim the fund you paid in your mail. If you win the auction, the item you bought will also be issued through mail. |4.Click the item‘s icon to view detailed info about it. |5.Auction contains a lot of rewards that you might have wanted to get but couldn’t, stay focused on the items. |6.Diamonds spent in auctions will not be counted into Spending Event nor Daily Quest."
