			"It’s been years ever since academy was built, and now we already have over 100 girls joined our big family! Who do you like most of them? Come and vote for her then!||1.During event, opening daily quest medal chests will gain you 2 Normal Votes, weekly medal chest will gain you no votes though. |2.Except Normal Vote, every 300 diamonds recharge during event will earn you a super vote. Super Vote will be hidden until the last 3 days of event. 1 super vote equals to 50 normal vote and it’ll also give the girl you supported 3 mysterious gifts! |4.When a BG has mysterious gifts, all players who vote for her might receive Mythra scrolls. You may send many votes to a girl at once to stack up the chance but you can only earn 1 gift anyways. |5.After mysterious gifts are fully distributed. The player who sent super vote will earn feedback rewards-Mythra scrolls. The amount of rewards he or she gains are based on how many votes did this girl gain before mysterious gifts are all sent out. |6.In the first 2 days of event, you may select 1 BG to support for free. If this girl you supported wins the 1st place, you’ll gain a special reward for supporting her! |7.The masters who are the No.1 supporter of the top 3 most popular girls will receive 1 Activation Card (detailed introduction of Activation Card could be read below.)and \"True Love\" tittle of that girl as bonus reward(3 person in total). The No.2 and 3 on the Supporter Ranking of the top 3 most popular girls will receive 1 Activation Card and \"Guardian\" tittle of those girls.(9 persons in total) |8. After event ends, the girl with highest support will gain LIVE effect of her card first. ||【LIVE】1. When LIVE function is online, players could enter the girl's info page from \"Girls\" to view and activate the LIVE effect. |2. Activation of the LIVE effect requires Activation Card and a few diamonds (Activation Card can be used to activate any girl who possesses LIVE effect.) |3. Once activated, the LIVE effect will appear synchronously on the page of BG girl, Girls, Library, Intimacy, etc"
		},
