			"CREATS_RULE1",
			"Sorcery War Rules:"
		},
		{
			"CREATS_RULE2",
			"Entrance Rules:"
		},
		{
			"CREATS_RULE3",
			"1.Sorcery War is made up of multiple individual campaigns.|2.Every campaign needs enough players join to unlock it.|3.Every player needs to consume one sorcery scroll to join the campaign.|4.Sorcery scroll is obtained from stamina consumption, every accumulative 3000 stamina will provide one sorcery scroll.|5.When number of sorcery scroll owns reached max limit, players can't get more sorcery scroll and stamina consumption won't accumulate.|6.Players can team up with any players in the same server, or cross server with player who is less than 5 academy levels higher/lower than self.|7.Single player could choose single mode to challenge sorcery war campaign directly.|8.Enemies in single mode are same with group mode, but players can send more girls than in group mode.|9.Reward calculate of single mode is the same with group mode."
		},
		{
			"CREATS_RULE4",
			"Battle Rules:"
		},
		{
			"CREATS_RULE5",
			"1.Every campaign is made of multiple areas, areas are linked by paths, each area has several groups of enemies. Locked area is in grey, unlocked area will be highlighted.|2.Every campaign will have different battle buff based on different boss.|3.Each group of enemy could be challenged in both single mode or group mode.|4.Same group of enemy could only appear in one battle at the same time.|5.There will be 1 minute preparation time for selecting girls before each battle，when time is out you will quit the battle and select again.|6.After each battle ends, girls' status of both side will be kept, but MP of pet will clear in the beginning of each battle.|7.Whenever sending a girl that never deployed will consume one quota, when quota all consumed, you could only deploy girls that had been sent to battle.|8.When the remaining time of campaign is less than 2min30sec, you can't start a new battle.|Raid function will be opened after you have complete the campaign once."
		},
		{
			"CREATS_RULE6",
			"Reward Rules:"
		},
		{
			"CREATS_RULE7",
			"1.Rewards after the campaign ends will be determined by your points, higher your points, more rewards you will get.|2.The clearance points is concerned with the completion of the campaign, every one percent of completion will gain you 10 points.|3.When the completion of campaign become 100 percent, girls not died, deploy quota not used, remaining time will all transferred into points based on certain proportion.|4.Players who join the same campaign will earn same points after campaign ends.|5.Raid rewards is based on certain proportion of highest historical points."
		},
		{
			"TOP_PROMO_RULE_TITLE",
			"鬥牛晉級賽規則"
		},
		{
			"TOP_PROMO_RULE_TEXT",
			"1.二週年感謝祭期間，點擊扭蛋機的扭蛋旋鈕，就可以消耗扭蛋代幣來抽取扭蛋。|2.扭蛋機中的掉落獎品可以在藏品列表當中查看，不同的獎勵擁有不同的稀有度，努力去收集稀有的獎勵吧！|3.每天首次登錄遊戲和每日任務獲得150活躍度後均可以獲得一枚扭蛋代幣。|4.活動期間，每儲值300鑚即可獲贈一枚扭蛋代幣，儲值600鑚即可獲贈兩枚，以此類推。|5.儲值的鑽石不累計，如果分別儲值400鑚和200鑚，則只可以獲得一枚扭蛋代幣哦~|6.扭蛋抽取動畫播放時，再次點擊扭蛋機旋鈕可以跳過抽取動畫。|7.活動結束後，多餘的扭蛋代幣將會作廢無法使用，一定記得提前使用。"
		},
