		{
			"LIANYI_GIVE_RULE_TEXT",
			"Masters, come and join this great  Thanksgiving Party! You can increase your popularity by sending gifts and increase your charm by receiving gifts. There are abundant rewards for you to claim when your charm or popularity reaches certain amount.|2.You need materials to craft gifts. There are 3 types of materials,Thanks Letter(S), Thanks Letter(M) and Thanks Letter(L).|3. You may obtain Thanks Letter(M) by clearing any campaign, joining 1 on 1 or Top Floor may gain you Thanks Letter(S) but you can only get Thanks Letter(L) through Event.|4. The gift you craft varies by the materials you used.|5. You can send and type gifts in any amount you want.|6. You can check up to 30 records of the gifts you received and you also can send gifts in return.|7. Sending 1 or more same type of red gifts, 10 or more same type of orange gifts. 30 or more same type of purple gifts will be announced in whole server.|8.After the event ends, the top 2-100 players on popularity ranking or charm ranking will be rewarded with Star of Popularity or Star of Charm. The No.1 player on these 2 rankings will relatively get  King of Popularity or King of Charm.|9.Title rewards: The the No.1 players on popularity ranking or charm ranking will be rewarded with King of Charm or Super Mixer, Charm LV10 players will get Star of Charm, popularity LV10 players will get Good Mixer. Title rewards will be distributed within 7 working days after the event ends. |10.All the items will be deleted after event ending, remember to use it during event."
