			"1.Every Friday’s 21:00. The top 1000 players in Junior group and top 100 players in Senior group can join Promotion. |2. Every Friday’s 21:00, the last 3000 players in Senior group and last 300 players in Master group will become the opponents for promotion match. |3.After the promotion match begins, system will randomly match players 3 opponents from upper group. Players can challenge any of them, but once the challenge starts, you won’t be able to challenge others. |4.Promotion match last till 2nd day’s 21:00.All players have 3 chances to challenge your opponent, if you gained 2 victories, the promotion will be approved, or it counts you failed. |5.The challenge in promotion match has 1 hour cool down. |6.Players in different groups need to win different amount of rounds.|7.If promotion succeeds, challenger will swap rank and scores with opponent, if fail, remain the same. |8.During promotion match, the challenged players still can challenge their opponents in their own rank. If the challenger succeeds in promotion. The rank and scores swapped will be what they have when the promotion succeeds."
