		{
			"ACTIVITY_SNOWBALL_RULE_TEXT1",
			"1. During event period, opening every daily quest medal chest will reward you 10 normal balls, but the weekly medal chest will not do so. |2. Besides free balls, you may purchase balls with diamonds directly. We have greatly increased the chance for normal ball to knock down the targets. |3. We also prepare a special ball for you which could be gained from other events! Using the special ball will give you 100% chance to knock down your targets! |4. Click the girls that are running on the field to hit them with your ball, if you successfully knock her down, she'll give you her scrolls as rewards! But do note this! The water balls you threw out cannot be reclaimed. |5. The special ball will be kept for next time but the normal ball will be automatically cleared after this event. |6. If you find some little creatures in the waterfield, knock them down and you'll earn special rewards for doing so! |7. You wil get scrolls of popular BG: Karaxes 's scroll, Tokugawa 's scroll, Javelin 's scroll, Wu Kong 's scroll, Amelia 's scroll, Wraith 's scroll, Ilian 's scroll, Nia 's scroll.And will get some random pet essence!"
