		{
			"ACTIVITY_SNOWMAN_RULE_TITLE",
			"Rules of Forest Smash"
		},
		{
			"ACTIVITY_SNOWMAN_RULE_TEXT",
			"Hey, Forest Smash has already begun! The forest guardian-Owl need your help to protect their home! Cultivate your own owl and help him participate in this Smash!||【Owl Raise】|1.During the event, you can use the Honey to increase the level, promotion and skill level of your Owl; Owl can be upgraded to Lv.100 at most; you can use Crystal Flower to increase the stats of Owl.|2. With the promotion increased, Owl will unlock more skills.|3. Each Crystal Flower can increase different stats values based on the current level of Owl.|4.Owl will unlock different skins, you can change them in the raising page.|5. The Honey can be obtained in the normal and elite campaign. Honey and Crystal Flower can also be obtained in the Capsule Toy. ||【Championship】|1. Each use of the Fighting Fire can allow the Owl to participate in the battle; Fighting Fires can be obtained by recharging accumulated 100 diamonds or from the Capsule Toy.|2.In the battle, the Owl can't use the skills except ults until the girls meet the requirments.|3.In the battle, the level and promotion of girls are same as the Owl. The girls can only use the skills that can buff Owl except the skills of recovering HP.|4.You will win as long as your Owl knocks down the opponent's Owl. Defender will win if time is out.| 5.You can get the special gems of Owl that you have defeated which can be used to exchange valuable gifts.|6.After the event, the top 100 players in the rank list will receive extra rewards.|| 【Capsule Toy】|1.During the event, daily login or getting 150 medals of Daily Task will be rewarded 1 token.|2.You can spend diamonds buying tokens, and buying more tokens can get the discount.|3.When you do not get the Rarest items, the used capsule will be automatically stored in the Recycle Box. When the Recycle Box is full, you can get the rarest item. The Recycle Box will be cleared once you get the rarest item.||【Championship reward】|No1: diamonds500, coins100000, a villa key, dragon manual*10 Summer Goddess*1|No2: diamonds400, coins90000, a house key, dragon manual*10 |No3: diamonds300, coins80000, a dorm key, dragon manual*10 |No4: diamonds200, coins70000, kanto food*10, dragon manual*5|No5: diamonds100, coins60000, kanto food*9, dragon manual*5|No6: diamonds100, coins50000, kanto food*8, dragon manual*5 |No7: diamonds100, coins40000, kanto food*7, dragon manual*5|No8: diamonds100, coins30000, kanto food*6, dragon manual*5|No9: diamonds100, coins20000, kanto food*5, dragon manual*5 |No10: diamonds100, coins10000, kanto food*4, dragon manual*5 |No20: diamonds100, coins8000, dragon manual*5 |No30: diamonds100, coins6000, dragon manual*5 |No40: diamonds100, coins5000, dragon manual*5 |No50: diamonds100, coins4000, dragon manual*5|No70: coins3000, dragon manual*5 |No100: coins2000, dragon manual*5 ||【Warm Tips】|All the items will be cleared after the event."
