		},
		{
			"ACTIVITY_SKIN_WARMUP_RULE_TEXT",
			"1. Yenn's new skin is coming! Now masters could support her! The more personal supports and server supports are, the more discount you will get in the later recharge event of Yenn skin.|2. Each master has a free daily support chance, after that each support will cost 100 diamonds.|3. After the server supports reach a certain amount, every master will get a public discount for Yenn's new skin! |4. When the personal supports reach a certain amount, you can get another personal discount for Yenn's new skin and other rewards even a cute frame for you to collect.|5.After Yenn's new skin released, you can get it at a price of recharging 3888 diamonds×(1-public discount)×(1-personal discount)."
		},
		{
			"DORM_TEXT",
			"Dorm"
		},
		{
			"FURNITURE_FACTORY_TEXT",
			"Workroom"
		},
		{
			"DORM_RULE_TITLE",
			"Notice for Dorm user"
		},
		{
			"DORM_RULE_TEXT",
			"1.Dorm will be unlocked when masters clear Chapter 7; House will be unlocked when masters clear Chapter 13; Villa will be unlocked when masters clear Chapter 20. Opening each kind of room requires \"Key\" which could drop in Chapter 20 or hidden boss. |2.One key can open one room.1 key for Dorm can open 1 type of room in 6 types Dorm room. 1 key for House can open 1 type of room in 6 types House room. 1 key for Villa can open 1 type of room in 3 types Villa room. Every type of room will grant girls different kinds of stats bonus. Every room in Villa, House and Apartment can accommodate 1 girl. Restroom can accommodate 5 girls. |3.Every type of room will grant girls different kinds of stats bonus, Villa has the highest basic bonus, and House takes the 2nd place after Villa. Restroom grants girls in it exp bonus. |4.Every room has its comfort level. Every room has 5 comfort levels besides restroom. The higher the comfort level of each room, the more stats bonus the girl living it will gain, after reaching lv5 of comfort, the bonus stats will not further. The higher the comfort level of restroom, the more exp girls in it will gain. Every time when you enter Restroom, the exp generated in the period from last time will be claimed. The exp in Restroom will only accumulate for 10 hours. If you didn’t enter restroom after 10 hours, it’ll save no more exp than these 10 hours. |5.You need to put into furniture into the house to increase its comfort level. Furniture can be crafted in Workroom or earned in some events. Materials and blueprints will drop in campaign. Different furniture will increase different amount of comfort level. |6.Every room except restroom has a Dresser built in, you may click Dresser to equip your girl with a set of make-up gears that only belongs to her. Dresser cannot be removed. |7. Any girls could live in the Dorm, House or Villa but only the girls who reach red+1 could use the Dresser and equip themselves with different make-up gears.|8.Once a girl enter a room, the room will enter a Cool Down, and rooms that are in Cool Down cannot switch its user. |9.Make-up gears in Dresser unlock with the girls’ star levels. 1 star BGs can only equip 1 make-up gear while the 5 star girls can equip 5. |10.Once the girl leaves a room, all effects from make-up gears and bonus stats will be disabled. Though entering a new room will activate the effects from make-up gears. |11.There are lots of interactions you may have with your girls in rooms. Try to put them into bed～|12.Every room has its original name, you can change it by clicking the window of name.|13.The rooms Cat Cabin, Warm Cabin, Sweet House, Cute House and Pudding Nest have a better attribute increase in Str.|14.The rooms Destiny, Rainbow, Butterfly, Blossom and Paradise have a better attribute increase in Int.|15.The rooms Autumn, Sunset, Maple, Bridge and Sakura have a better attribute increase in Agi.|16.Only Villa could be extended three times. Each extension requires a different Extend Permit and a certain amount of Cement. |17.Each extension completed will increase the Comfort cap for the Villa."
