			"RED_ENVELOPE_RULE_TITLE",
			"Rules of Red Packet"
		},
		{
			"RED_ENVELOPE_RULE_TEXT",
			"Knock, knock, knock...treat or trick? Halloween is coming! Are you ready? Abundant diamonds in the candies are waiting for you. Grab them as possible as you can! The top 3 players will be rewarded with the newest frame Jack-O'-Lantern. You could carry it to scare the ghosts!|Notice:|1.Cumulative recharge will not be counted cumulatively. But you can get repetitively rewarded for the amount of diamonds you recharged if they have reached the goals of rewarding you candies. For instance, if you recharge 300 diamonds for 10 times, you'll get 10 candies from 300 diamonds level.|2.The candies now can stack up and your recharge will be calculated separately to make the best use of them. If you recharged 10000 diamonds during event, you'll get 1 candy from 6000 diamonds recharge, 1 candy from 3000 diamonds recharge, 1 candy from 600 diamonds recharge and 1 candy from 300 diamonds recharge. In total there are 9900 diamonds recharged counted. If you recharge 20000 diamonds, it'll be 3 candies of 6000 diamonds and 1 candy from 1200 diamonds. 1 candy from 600 diamonds recharge, in total they'll make 19800 diamonds counted.|3.Every candy you send will reward you marine telescopes. Sending 300 diamonds candies gives you 3 marine telescopes, 600 diamonds candies gives you 6 marine telescopes and so on.|4.Opening candies rewards you marine telescopes as well, but you can only get up to 5 marine telescopes per day from opening candies during event.|5.Now players can open up to 20 candies everyday, to make it more fair."
