		{
			"ACTIVITY_GAMBLE_RULE_TEXT",
			"1、競猜分爲三個階段，下注階段、挑戰階段和開獎階段。|2、下注階段為幻想鄉開啓的前一天，學長可以在本階段進行下注，猜下一次幻想鄉合作模式全服排名第一名傷害的個位數是多少。|3、每個數字都可以進行下注，單個數字下注的金額有上下限，下限為1000，上限為50000000。|4、點擊數字可以調整下注的金額，下注界面會顯示目前每個數字的下注金額，點擊下注按鈕會消耗對應數額的金幣進行下注。|5、第一次下注後，在下注階段結束前可以修改下注的金額進行加注，點擊加注按鈕會消耗加注的金幣。|6、下注或加注前，可以通過點擊重置按鈕，將下注的金額重置為上一次下注的狀態。|7、下注階段結束后，將無法進行下注，同時進入挑戰階段，本階段請學長盡情與好友合作挑戰boss吧！|8、幻想鄉關閉后，進入開獎階段，此階段活動關閉，開獎情況和金幣獎勵將會以郵件的形式發送給各位學長。|9、祝各位學長都能獲得幸運女神的青睞，中得大獎！"
