		{
			"STICK_BLESS_TEXT_RULE",
			"1. During the event, you may get Sakura by clearing campaigns, drawing certain vending machines or purchasing with diamonds.|2. Every Sakura you use will take one part in the Reward Area and you'll get the item in that part as reward in the meantime.|3. While the animation of Sakura is being played, clicking the \"Enjoy\" button or any reward part allows you to skip to the result.|4. Every 5 Sakura you use will grant you 1 chance to Evade which will remove 1 part in the Reward Area so that you can avoid getting that reward. One thing to note is that all Evade chances you have will disappear once you reset the Reward Area.|5. You can reset the Reward Area any time you want and the rewards are randomly selected from a default reward pool. All parts that are marked by Sakura or being removed will reset as well. You have 1 free chance to reset the Reward Area every day, while from 2nd reset on, they will cost you diamonds.|6. Every Sakura you use will grant you 1 Dessert. Dessert can be used to exchange awesome rewards!|7. All the event items will be expired after the event ends. Please use them during the event.|8.In acquirement, the Sakura you can get will have a maximum.|9. Ranking Rewards:|Rank 1-3: Villa Key*1, Extend permit Ⅲ *1;|Rank 4-10: Extend permit Ⅲ *1;|Rank 11-50: Extend permit Ⅱ *1."
