		{
			"EVENT_CENTRE_RULE_TEXT",
			"1.There are 3 types of materials useful in Workshop: Magic Powder, Magic Liquid and Magic Energy.|2.Cabinet is the place where you can upgrade your \"Textbook\", the acquirement of different Textbooks varies in game. For instance, you can get Textbooks from Main Quest, Elite Campaign, Challenge Mode.|3.Recycle Bin can be used to dissolve the gears, which gives you materials that can be used in Workshop. Dissolving gears consumes Recyle Bags, the amount of Recycle Bags it consumes is depended by the quality of the gear, and the material from dissolvement will vary with the gear quality. Tap&hold the trashbin icon to view how long it takes till Recyle Bags are fully restored.|4.Bookshelf has no level cap, and you can upgrade Bookshelf with magic exp, which comes from the study of Textbooks in Cabinet.|5.Cabin, a place that allows you to craft pet gears with Lolipop. The higher the level of Cabin, the better the gears you can craft. Different pets allow you to craft different gears.|6.Workbench is for you to craft gears of girls, the higher the level of it, the better the gears you can craft.|7.Admin allows you to exchange materials under a certain ratio. The more you exchange, the more expensive you'll need to spend."
