		{
			"ACTIVITY_SAKURA2018_RULE_TITLE",
			"相約櫻花祭活動規則"
		},
		{
			"ACTIVITY_SAKURA2018_RULE_TEXT",
			"【果子作坊】|1.活動期間，通過或掃蕩副本有概率獲得糯米，每累計消耗300鑽石可獲得一個豆沙（愛心拍賣會消耗鑽石不算在內），通過發放或搶得櫻花福袋可獲得櫻花。|2.在果子工坊中使用糯米、豆沙、櫻花這三種原材料，就可以製作各種櫻花小點心。|3.果子工坊中的劉禪會主動吃掉你製作的櫻花點心，並且心情會根據對點心的喜愛有不同程度的變化，滿足度UP！|4.當劉禪的滿足度達到一定程度後，她就會與你兌換不同的活動獎勵。|5.請注意，上一屆櫻花祭的櫻花點心已經過期，不能食用了喔！||【踏青尋寶】|1.踏青總共分為9個區域，在每個區域探索都能夠找到各不相同的特殊物品獎勵。|2.每探索一次都會消耗一個當前裝備的探索道具，不同的探索道具可以起到不同的探索效果，比如一次探索多個格子，或使探索到的道具翻倍等。|3.探索道具可以通過活動道具商店購買，也可以在探索的過程中隨機獲得。同時櫻花祭登錄送不停活動中通過每日登錄也可以獲得一些探索道具，請不要錯過！|4.在擁有道具處點擊不同的道具圖標，可以切換選擇不同的探索道具。|5.在每一層的探索中發現並且點擊下一層入口，才能夠前往下一層繼續探索。|6.通過重新開始按鈕可以放棄當前的探索進度，從第一區域開始重新探索。需要注意的是，每一區域獨有的特殊物品不會重複獲得，在發現一次過後就沒有了喔。||【櫻花福袋】|1.活動期間，通過儲值鑽石即可獲得數額不等的福袋，例如儲值900鑽，可以獲得300與600檔位福袋的發放機會各一次。|2.福袋發出後，優先點擊福袋的前幾名玩家才能夠搶得福袋，會獲得隨機數額的鑽石。|3.福袋發出後，發送者即可獲得固定數量的櫻花作為獎勵，同時搶得福袋的玩家也有機會獲得少量櫻花。"
		},
