			"1.During the event, masters could plant various flowers to harvest and you will get the Nectar as a reward which can be used in the Shop of Store to exchange rewards.|2.The planting seeds can be purchased in the shop with diamonds or Gold Pea obtained from recharge.(Recharge 1 diamond=1 Gold Pea)|3.Flowers can only be planted in the planting area that has been weeded, and the area with weeds requires diamonds to weed before planting.|4. With the growth of flowers, there may be water shortage, please water the flowers in time or it will affect the final harvest!|5.You can visit your friends' or club mates' gardens to help them water their thirsty flowers, also secretly help them harvest (steal) some flowers.|6.The unused seeds in your account will be automatically sold as coins before next Flower Garden coming again.|7.The Top 10 players will get Title after event ends!|8.The flower seeds that haven't been planted will be sold by system and the coins will be added to your account automatically when this event opens next time.|9.You can go 『Supply』→『Pack』and buy Irrigation pack，then you can turn on Auto Irrigation. But it will expire after the event ends."
