		{
			"STONE_EVOLUTION_RULE",
			"1. This function is open after your academy level is Lv80, and only girls who meet the conditions can break through. |2. There are 3 stages. Stage 1: Lv80 with 3 stars; Stage 2: Lv90 with 4 stars; Stage 3: Lv100 with 5 stars. Only when the girls meet the conditions and finish the process of the stage, she can step to the next stage. |3. Girls can only use their own scroll to break through. Each time will consume 1 scroll. |4. Max HP will be increased by 180. |5. Physical defence will be increased by 4. |6. Spell resistance will be increased by 4. |7. HP regeneration will be increased by 80. |8. MP CONSUMP REDTN will be increased by 45. Every 100 points will increase by 1%. |9. Nor-Upcap Ticket can replace scrolls of normal girls. |10. Adv-Upcap Ticket can replace scrolls of normal and special girls. |12. Upcap Tickets are not available for some girls."
