			"ACTIVITY_GOOGLE_NOTICE_TEXT2",
			"1.在Android手機或平板電腦上開啟Google Play商店應用程式|2.依序輕觸左上“選單”圖示，點選“賬戶”進入“新增付款方式”|3.點選“啟用電信代扣功能”|4.按系統指示輸入相關資訊|5.系統會在您的Google賬戶中加入新的付款方式"
		},
