		{
			"ACTIVITY_GOOGLE_RULE_TITLE",
			"Google Play限時折抵規則"
		},
		{
			"ACTIVITY_GOOGLE_RULE_TEXT",
			"1.2018/7/1至2018/8/31，在 Google Play 選擇電信帳單代收付款，首次購買任一品項，首筆付費將依用戶實際交易金額回饋電信帳單現金折抵，最高可享 60 台幣折抵。|2.若交易金額為 60 台幣(含)以下則依實際交易金額折抵；若交易金額為 60 台幣以上則最高可折抵 60 台幣。|3.現金折抵並不僅限本活動頁面儲值禮包，只要滿足規則1所述條件，在《我的學妹不可能那麼萌》中儲值購買任意商品均可享受現金折抵。|4.僅使用電信帳單代收付款的首筆付費可享受優惠，若您在《學妹》以外的地方使用了GooglePlay電信帳單代收付款方式，則無法再在學妹中獲得現金折抵優惠了喔~|5.本活動頁面禮包本身不限制儲值購買方式，但是用其他方式無法獲得現金折抵優惠。|6.本活動頁面的兩個儲值禮包在活動期間均只能購買一次。"
