			"PEAK_RULE_RANK_TEXT_OLD",
			"你的鬥牛排名是%d名，保持當前排名，可領獎勵為"
		},
		{
			"PEAK_RULE_RANK_TEXT2_OLD",
			"你的鬥牛排名是%d名，保持當前排名，可領獎勵為"
		},
		{
			"PEAK_ARENA_RULE_TEXT_1_OLD",
			"你的鬥牛排名是%d名，保持當前排名（第%d至第%d名），可領獎勵為："
		},
		{
			"PEAK_ARENA_RULE_TEXT_3_OLD",
			"鬥牛戰鬥規則："
		},
		{
			"PEAK_ARENA_RULE_TEXT_4_OLD",
			"1.每週日晚上22點整發放排名獎勵，通過信件發放。在獎勵結算後積分不重置。|2.鬥牛戰鬥自動進行，玩家不能手動施放技能。|3.在鬥牛中，所有戰姬血量及治療效果經過相同幅度上調。|4.玩家可以隨時調整自己的防守陣容，必須設置三隊戰姬，每隊戰姬至少1人。|5.戰鬥中採取三戰兩勝制，先勝兩場者勝出。|6.消滅對方全部戰姬獲得勝利。|7.戰鬥超時，存活戰姬多的一方取得勝利。|8.存活戰姬數量一樣時，總傷害高的一方獲得勝利。|9.總傷害一樣時，防守方獲得勝利。|10.三戰兩勝結束若進攻方勝出，則獲得一定的積分，防守方失去一定的積分。獲得和失去的積分都有上限值。|11.獲得的積分只與被挑戰的玩家有關，挑戰積分高於自己的玩家能獲得較多積分，挑戰積分比自己低的玩家只能獲得較少積分。|12.主動挑戰失敗時，不扣除積分。|13.每天每個玩家可以免費挑戰對手5次。每天淩晨5點整重置次數。每天前10次挑戰對手時能獲得額外鬥牛幣獎勵。|14.每次挑戰後，發起挑戰的玩家進入10分鐘的冷卻時間。|15.排名前三名的玩家會隱藏全部陣容，3-20名的玩家會隱藏兩條隊伍，50名以後的玩家將不會隱藏隊伍。|16.每天晚上22點到第二天早上8點無法進行鬥牛。|17.被其他玩家挑戰成功時可以復仇該玩家，復仇成功一次後該玩家從復仇名單中去除。|18.挑戰者積分大於等於被挑戰者積分數額2450分時，則挑戰者獲勝後不增加積分。"
