		{
			"ACTIVITY_WISH_RULE_TEXT",
			"1. Consume 『Sakura』 to throw a wish for event (within 50 characters). After the wishes reach the certain times, you can collect the corresponding rewards.|2. Using cumulatively 50,100,200,400,600,800,1000,1500,2000,2500,3000 stamina at most will all give you Sakura, you can directly 【collect】 on the bottom~ |3. You may get Sakura from Academy Boss and Server Tasks!|4. If you send text including 『P-A-R-T-Y』 at 20:08 everyday during the event, you will have chance to receive special prize, only once a day~|You have 50% chance to gain word \"R\" for each wish. "
