		},
		{
			"ACTIVITY_DIGLETT_RULE_TITLE",
			"Whac-A-Mole Rules"
		},
		{
			"ACTIVITY_DIGLETT_RULE_TEXT",
			"Himoto's cousin has pretended to be Himoto, and is messing the festival up. Let's get rid of her~ |1. You can get scores by hitting Himoto's cousin in Whac-A-Mole. You can redeem items by scores(click the Exchange button). The system will only count the scores in normal modes. It won't count the scores in challenge mode.|2. Spending 200 diamonds, then you can enter the normal mode. You will have 1 minute each time you enter the normal mode. There are 3 species Mole: Yellow moles give 1 score, Pink mole give 3 scores And black mole give -5 scores.|3.After 5 times normal mode, you will have 1 chance for infinite mode. There is no time limit in Infinite Mode, but it will end when you miss three hits or hit Black Mole three times.|4. After normal mode, you can click Tenfold to get 10 times of scores. And you will get corresponding times for infinite mode too.|5. In the infinite mode ranking, the player who can gain more scores will get higher rank. At the end of the event, awards will be sent to you according to your rank. Top 10 player will receive limited title \"Gopher Planing\"！"
		},
		{
			"ACTIVITY_BOSS_RULE_TITLE",
			"Acad Boss Rules"
		},
		{
			"ACTIVITY_BOSS_RULE_TEXT",
			"The academy boss--Kratos.Lily has came, she has ten types! She will challenge all masters!|1. During the event, the challenge will open at 10:00, end at 22:00.|2. You can get the 『Entrance Tickets』 from Infinite Mode in Whac-A-Mole.|3. Kratos.Lily can be defeated every day, but whether she is defeated doesn't affect the ranking.|4. Kratos.Lily has different types according to different stage. Masters need to change your team depending on the type.|5. During the challenge, your girls will be set as lv 100 and red +1 with full enchanted gears.|6. About the individual total damage reward:| you will receive rewards once reaching damage different stages.|7. About Rewards:|You will get relating rewards after each challenge, rewards are showing below：|Reach 500000 damage:Word's\"Y\"*1，Sakura*1，Copper Coin*1|Reach 1000000 damage:Word's\"Y\"*1，Sakura*2，Copper Coin*1|Reach 3000000 damage:Word's\"Y\"*2，Sakura*3，Copper Coin*1|Reach 5000000 damage:Word's\"Y\"*2，Sakura*4，Copper Coin*1|Reach 7000000 damage:Word's\"Y\"*3，Sakura*5，Copper Coin*1|Reach 9000000 damage:Word's\"Y\"*3，Sakura*6，Copper Coin*1|Reach 10000000 damage:Word's\"Y\"*4，Sakura*7，Copper Coin*1|8.Besides the total damage and challenge rewards, you could also receive the daily ranking rewards at 22:00 every day，here are Daily rewards:"
		},
		{
			"ACTIVITY_WORD_RULE_TITLE",
			"Words Collection Rules"
		},
		{
			"ACTIVITY_WORD_RULE_TEXT",
			"1. Masters can collect words during the event, and you will get great rewards if you collect them all. |2. There are fixed collocations for words, you can't compound the words which are not in the collation.|3. The ranking is for times of \"PARTY\" collecting times.|4. How To Obtain Words：|P：Treat Bag|A：Treat Bag|R：Wish Candle|T：Whac-A-Mole shop|Y：Acad Boss Single Challenge.|5.To send letters, Masters need to reach level 45.|6.TOP 10 players in ranking will receive Title \"Stunning Beauty\". The ranking rewards details are shown below:"
		},
