		{
			"ACTIVITY_LUCKBAG_RULE_TEXT",
			"1. Use Copper Coins, Silver Coin, Gold Coin to draw the corresponding Lucky Bags.|2. You can get Copper Coins from Whac-A-Mole's exchange. |3. You can get Silver Coin from small Lucky Bags and also Wishing Tree. |4. Every cumulatively 200 diamonds recharge gives you a Gold Coin~|5.Click the Lucky Bag in the middle to preview all the rewards in the bag."
		},
