		{
			"ACTIVITY_RICH_RULE_TEXT",
			"【Map】|(1)Get Dices: You can directly spend diamonds to buy dices in Dice Store or gain from other events. Click the Dicing to roll the dice, your girl will move steps forward according to the number on the dice. |(2)Get Stars: Different events will be triggered according to the grid where the girl stays after moving. When your girl stays at the number grid, you will gain same number of Stars. |(3)Get Rich: When your girl stays at ★Sushi Bar, ★Bakery Cafe, ★Restaurant or ★Burger Girl, you could invest some gold coins to level them up. After that, every step you move will accumulate a certain number of gold coins which will be claimed automatically when your girl stays at these grids again. The higher level, the more income, level 3 at most. Bank will reward you diamonds but you can only invest it once. |(4)Random Events: If your girl stays at “?”, something special will happen: Hurricane (move to random grid, but the event in the grid won’t be triggered), Collapse (one of your investment shops collapse, disappear if it is Lv.1), Quality Problem (one of your shops’ interest decreases to 0. If you don’t have investment, nothing will happen), Theft (one of your Bag items is stolen), Text Fraud (lose some Stars), Free Trial (gain a random Bag item), Bank Bonus (Bank’s interest increases and you will gain more diamonds), Popular Store (one of your shops’ interest increases and you will gain more gold coins), Lottery (gain some Stars), Hitchhike (move forward as the same number as last Dicing), Restriction (the girl will turn back). |(5) Before the next Richman, stars and all items will expire, please remember.||【Star Shop】|You can buy items at the Star Shop. There are three items there: ★Cheat dice(roll the number you want), ★VIP card(help you in Sky Wheel, Pipe War and Warrior), ★Avoid card(to avoid the adversity in special events). Also there are some rare girls and items~||【Warrior】【Pipe War】【Sky Wheel】|Please view the Illustrations to get details about rules and rewards.||【About Scores】| There is a Ranking based on the scores you gained. Every time you defeat a boss of Warrior, you will gain 2 scores. Every time you light a room of Sky Wheel, you will gain 3 scores. Every time you finish Pipe War, you will gain 10 scores. Top 10 will get Rich Man title, Top 60 will get Gamble Master Frame (They will be sent to you in 7 working days after the event ends). Also, at the end of the event there will be a Ranking reward as showing bellow:"
