		{
			"ACTIVITY_CHOCOLATE_FRUIT_RULE",
			"1. In Fruit Catching, you can get scores by delivering fruits and catching stars. You can redeem items by scores. The system will only count the scores in normal modes. It won't count the scores in infinite mode. |2. Spending Fruit Ticket or Spending diamonds, then you can enter the normal mode. You will have 1 minute each time you enter the normal mode. |3. After several times of normal mode, you will have chance for infinite mode. there is no time limit but this will end after hitting the bomb several times. |4. After normal mode, you can click Tenfold to get 10 times of scores. And you will get corresponding times for infinite mode too. |5. In the infinite mode, each stage you pass, you will gain one more Reset Ticket. |6. In the infinite mode ranking, the player who can gain more scores will get higher rank. At the end of the event, rewards will be sent to you according to your rank. Top 20 player will receive limited title~ Top 50 player will receive limited frame~"
