		{
			"ACTIVITY_CHOCOLATE_AWARD_TIP8",
			"【Rules】|1. You can use Jingle Bell to pull rewards here. |2. There will be a rarest prize from pool 1 to 5. You can click Next to the next pool after you get the prize. For the rest pools, you have to pull all the rewards in the pool, then you can step to the next pool. |3. Pools are unlimited, but after pool 9, you need to use Next-Pool Ticket to step to the next pool. From pool 10, rewards in the pool won't change. |4. You can get Next-Pool Ticket from Infinite Mode in Fruit Collection. You can get one Next-Pool Ticket for each stage in Infinite Mode. |5. After the activity is closed, you can't get more Jingle Bell, but Essence Shop will be open additional three days for you to pull the rewards you want~"
