		{
			"ACTIVITY_CHOCOLATE_RULE_TITLE",
			"Rules of Frost Adventure"
		},
		{
			"ACTIVITY_CHOCOLATE_RULE_CONTENT",
			"【Event Description】|1. You can challenge campaigns in the \"Snow Adventure\", pass them and you will get rewards prepared by us. Every stage will have stars grade. You can get additional rewards by accumulating a certain number of stars too! |2. Each stage will consume you stamina and give you academy Exp and certain amount of 〖Jingle Bell〗. The higher chapter will give you more amounts of 〖Jingle Bell〗. You can spend 〖Jingle Bell〗 in \"Essence Shop\" for pulling rewards. |3. You can not raid stages those you don't have 3 stars grade. You can raid 3 stars stages by 〖Raid Ticket〗. |4. Different stages will give you different amounts of 〖Jingle Bell〗, which can be viewed in the illustration. |5. Cerberus, Hottie, SP Lightin, Werewolf, Harley will get 100% bonus AP in the battle. |6. As long as you possess the skins: Octopus Cuisine(Selene's skin), Wild Whisper(Cerberus's skin), Arcane Talent(Jyaku's skin), Green Hand(Yukimura's skin)(no matter in Bag or equipped), each kind of the 4 skins will give you 25% bonus 〖Jingle Bell〗. |6. After the event, the items unused will be converted to gold coins and sent to your Mail.||【Event Items】|1. Jingle Bell: drop from the campaign challenge in \"Snow Adventure\" and used to pull rewards in \"Essence Shop\". |2. Game Token: obtained from \"Snow Adventure\" or pack events and used to pull once in \"Frost Game Hall\" for free. |3. Fruit Ticket: used to challenge once in the normal mode of \"Fruit Collection\" for free and obtained from \"Essence Shop\" and \"Frost Game Hall\". |4. Reset Ticket: the reward in \"Essence Shop\" after 9th pool and used to enter the next pool, obtained from the infinite mode of \"Fruit Collection\"."
