		{
			"CHRAGE_TIPS_TITLE_CONTENT",
			"1. The purchase of Packs will not be counted to VIP points nor to Recharge Events.|2. If you encountered the delivery delay of purchased items by recharging using Android device while your fund is deducted. Kindly reach our in-game GM or Facebook Support, or at our gxb.carolgames.com, and providing us with your payment receipt. Our GMs will resolve your issue in no time once they receive your reports regarding such problems.|3. If you are recharging via Appstore and encountered issues of not receiving purchased items after payment. Once the receipt titled as \"Your invoice from Apple\" is sent to your mail while the purchased items are still yet to be delivered. Please use the \"Report a Problem\" function to contact Apple Customer Support for help.(Sorry for the inconvenience but Apple order numbers are not viewable from our side, so this is the only solution.)|4. If your recharge was to obtain items in limited-time events and this delay's occurrence caused you unable to achieve it, kindly send the screenshots of your order receipt to our GM through Facebook or email, we'll send you the items once we have verified it.|Tips: If you have any trouble with your recharge, please contact our GM and we will respond you as soon as possible."
