		{
			"ACTIVITY_TUTOR_RULE_TEXT",
			"1. Players above LV.20 can take part in.||2. There are 7 courses waiting for you. You have 3 times for each course every day. Times will reset on 5 am.||3. In the challenge of Extra Tutoring, you can only use the girls offered by the system. These girls are selected by the system randomly, and available once to the corresponding course.||4. You have different girls list in different courses.||5. If you fail in the challenge, it won't cost you daily times nor girls available time.||6. Girls offered by the system are LV.100, ss+1, awakened/blood awakened, full gears, full enchanted, 3 stars. Others depend on how your academy is. ||7. If you buy or have textbook items, you can use them for increasing stars of BBF girls. These items will expire after the event ends. ||8. Completing courses with 3 stars will unlock the BFF in corresponding functions. You are able to borrow a girl from some extra girls in the BFF. If you lead a girl from them, then you can't borrow the girl from your guild. This BFF will only available when this event is on.||9. Girls' levels and skill levels are related to your academy level. Awakening or blood awakening is related to the levels."
		},
