		{
			"ANNIVERSARY_GACHA2_RULE_TITLE",
			"Rules of Capsule Toy"
		},
		{
			"ANNIVERSARY_GACHA2_RULE_TEXT",
			"1.During event, masters may roll the stick of Gashapon machine with Gashapon coins. |2.Obtainable rewards in Gashapon machine can be viewed in “Collection”, different rewards have different rarity, get the rare rewards as much as you can! |3.Every day’s 1st login and obtaining 150 daily quest active medals will both reward you 1 Gashapon coin. |4.During event, every 300 diamonds recharge will earn you 1 Gashapon coin, 600 diamonds recharge will earn you 2 and so forth. |5.The separate recharges will not be accumulated. For instance, if you recharge 400 diamonds and 200 diamonds separately, you will only earn 1 Gashapon coin. |6.When the animation of rolling rewards is playing, you may click the stick again to skip it. |7.After event ends, the unused Gashapon coins will be deleted, do note to use them all during the event!|8.Now capsule toy has a guaranteed Rarest Reward for you if you didn't get a Rarest Reward with 60 pulls. The reward will be 1 rarest reward from all of them."
		},
