		{
			"MARCH_RULE_TITLE",
			"Rules of Champion"
		},
		{
			"MARCH_RULE_TEXT",
			"Wealth, partner, strength|All you want is here.|You shall stand above us all after suffering frustration, failure, even death.|Once you are powerful enough, then you can claim everything, including me.|                                                                                  ——Hottie|| Vanguard Rules: |1.Girls above level 65 can join the Vanguard. Masters who own multiple teams are recommended to use Vanguard. |2. The Vanguard can only be used when Champion has not been challenged manually. |3. You can use borrowed girl in the Vanguard lineup, but it will be counted in the Champion borrow chance. |4. The system will rate according to the total attack power of the 5 members of the Vanguard. The higher the rating, the more levels can be passed. Masters, please match the lineup as reasonably as possible. |5. Every day there will recommended girls, using recommended girls in the lineup can get a huge bonus. |6. The Vanguard will all die after being dispatched.You can only use the remaining girls to finish the reset champion stages. Masters, please carefully choose the lineup. |7. Use the Vanguard you can get Reagent. Masters can use Reagent by clicking girls' portraits. It will increase girls' energy after using the Reagent, the Reagent will be cleared next day.  ||Battle Rules:|1. In Champion, HP and SP of girls from both sides will not be reset.|2. Fallen girls cannot be revived.|3. When battle time ends, then consider both 2 sides lose.|4. Only 1 chance for every player daily.|5. After winning a battle, players can unlock treasure chest to gain abundant rewards like coins, gears, scrolls, and small chance to win battle girl.|6. Players who defeat the 9th opponent in Champion can gain the access to Mystic Chest, by spending 50 diamonds to unlock Mystic Chest for abundant rewards. After Champion reset, Mystic Chest also will be reset whether remain locked or open.|7. Not only you can collect Champion Trophy from treasure chest, but also exchange abundant rewards in Champion Exchange(inside Store)."
		},
