		{
			"ACTIVITY_DREAMWORLD_RULE_TITLE",
			"Rule of Endless Maze"
		},
		{
			"ACTIVITY_DREAMWORLD_RULE_TEXT",
			"1. Masters need to be at least level 65 to join this event.||2. It will cost you 1 clock each time you enter the challenge. ||3. Masters will get 1 clock at the beginning of the event. During the event, you will get another clock at 5:00 am every week.||4. For every 4200 stamina spent, you will get a clock, and you can get 2 times per week by spending stamina. In addition, you can also purchase in some related events. ||5. Masters are free to choose the difficulty of the challenge. Plot mode will be relatively simple, and the battle in the challenge mode will be difficult.||6. In the challenge mode, masters receive more rewards than the plot mode. In addition, the completion of the plot mode achievement and the completion of the challenge mode achievement give different rewards. ||7. In the plot mode, masters can use all the girls and pets in the current game, the attributes are unified to: 5 stars, red 1 quality, level 100, Full skill level, full equipment enchantment, full awakening / Blood awakening, other attributes are not counted; each girl and pet will have 5 minutes of cool down after one use. No cool down if the battle failed. ||8. In the challenge mode, masters can only use their own girls and pets. Each girl and pet will have a 10-minute cool down after one use. Dead or failed will also lead to cool down. At the same time, you can choose to reset the CD by spending 100 diamonds. ||9. Achievement progress and rewards will not be reset during the event||10. During the event, every 7 days, the map of the Endless Maze will enter the next lap and change. But only when you start the challenge again can you enter the new map||11. During the challenge period, masters can choose to give up this challenge at any time, but the consumed clock will not be returned.||[Hint]|Your relationship with Nona and Katie will affect the ending of Endless Maze, do remember to think carefully about each dialogue option!"
