		{
			"ACTIVITY_ANNI_UFOCATCHER_RULE",
			"1. The Claw Machine can catch items manually or automatically. Catching items manually costs tokens or diamonds, and catching items automatically costs value coupons. Every 200 diamonds recharge you will gain 1 Value Coupon bonus.|| 2. Using a Claw Machine cost a Claw Token or use diamonds. For a certain time period, move the crane above the item that you want. After tapping the grab button, the crane starts grabbing the item. ||  3. Catching manually has a chance of failure. You can try catching something again if you fail to catch it as long as you do not exceed the time limit.  Once you exceed the time limit, you will receive some randomly chosen prizes. ||  4. You can use a value coupon for to catch automatically. 10 value coupons is used for catching 10 items automatically. Catching automatically gives random reward from the Claw Machine.  ||  5. Tap the refresh button to reset the arrangement of items in the Claw Machine by consuming diamonds.  || 6. Every time the Claw Machine catches something, it will get a certain number of Yellow pigment. After catching some times, you receive gift bag.  ||7.You can switch the Claw Machine prize by clicking the button on the top left corner, at the same time, the gift bag rewards will change. ||8.The Claw Machine tokens and Value Coupon bonus will be cleared after the event."
