			"1. You can grab different ores for money in Gold Mine Event. There is a chance to get a time accelerators, bombs, gold water items or money in the bag. Once the time accelerator is used, the grasping speed of the gateway will increase. The current ore will be blown up by the bomb after they are captured. Once gold water is used, the stone can be turned into the gold mine of the same size. They won't be saved for next time you play.| 2. Normal Mode requires diamonds or Miner Ticket to enter. Each challenge has four stages. If the target number of money is not met, the challenge ends immediately. | 3. In Challenge Mode, if the target number of money is not met, the challenge ends immediately. When in Challenge Mode, there will be a number of items which must be used in order to win. Money in Challenge Mode will not be counted in the exchange shop. After the game ends, you can receive red pigment which is used for the Color Diary Event.  | 4. Finishing once in normal mode will give you 1 time counter for the challenge mode. After some time counter, it goes to 0 and allows you enter challenge mode once.| 5. After Normal Mode is over, you can double the money and also the times counter for challenge mode. Money can be exchanged at stores. |  6. The higher the number of money in challenge mode, the higher your ranking. |No.1-10:Gold Predator title, Miner Talent frame, Coco Essence*80. |No.11-20: Miner Talent frame, Coco Essence*40. |No.21-30: :Miner Talent frame, Coco Essence*20. |No.31-50: :Miner Talent frame.|7.Miner Ticket will be cleared after the event."
		},
