		},
		{
			"FOURTH_ANNI_PAINT_RULE_TEXT",
			"1. There are a total of 6 assigned paintings. Complete each one to receive a prize. Collect different colors of paint material to paint. || 2. Choose the paint that you own, and tap on the letters of a cell to paint (Letters that are connected can be painted at one time). || 3. The paint material needed to paint consists of the following colors: red, blue, green, yellow, white, and black. If you do not have enough number of certain pigment, you cannot painted. The paint materials must be obtained from other activities. || 4. Yellow pigment can be obtained in Claw Machine Events, red pigment can be obtained in Gold Mine Event, and the other four pigments can be obtained in black or white. || 5. After the six assigned paintings are complete, you can paint freely without spending paint. When painting freely, the whole canvas can be cleared by clicking on the eraser in the lower right corner. You can tap to erase parts of the canvas or the whole thing. When you exit free painting, you can click on the confirmation option to save your work. || 6. You can spend Like Ticket to vote for your favorite paintings. The ticket can be got from other activities. According to the number of points that are praised, the top 50 receives an new frame, and the top 10 receives an new title. || 7. Visit buttons allow you to see other people's freely painted paintings. If you want to hide your painting, you can tap the hide painting icon~"
