			"Is this a real Mafia Legend? More mysteries wait for your exploration!| 1. Gold Miner Event is coming to campus. How many gold mines can you dig? | 2. I heard that many girls like dolls very much. There is a Claw Machine with dolls for this celebration. Go and fetch the lovely dolls for the lovely girls.|3. In the event, you can get different kinds of colors of pigments from the Gold Miner and the Claw Machine event. Pigments can be used to paint in the Painter~ Rich prizes are also prepared for those who completed the pictures. Come and get it~|4. [Calw Token] Spend it and you will get one chance for Claw Machine. |[Value Coupon] Spend it and you will get a random prize with higher chance for better prizes. |[Time Machine] To start over in black and white.| [Paper] You can redeem rewards by this in black and white! |[Miner Ticket] Spend it and you will get one chance for Gold Miner. |[Pigments] Paint with them in Painter and get great rewards!| [Like Ticket] Vote for your favorite painting in Painter.|5. [Calw Token] [Value Coupon] [Paper][Pigments] [Like Ticket][Time Machine] will be cleared when event ends. Please use them in time!|6. In the last 3 days of the event, you can use the following  functions:|Campaign shop:Yes|Gold Miner Shop:Yes|Claw Machine:No|Painting:Yes|Event campaign:No|Gold Miner normal&challenge:No|"
