		{
			"CROSS_ARENA_RULE_TITLE",
			"Champion League Rules"
		},
		{
			"CROSS_ARENA_RULE_TEXT",
			"About the Champion League|(1) The Champion League group will be automatically matched according to your current academic level. The matching rules are as follows:|*group C: 70-89 etc./group B: 90-99 etc./group A: 100 etc.|(2) The entire season lasts for 30 days.|(3) Season rewards are divided into the following:| * Daily reward:|It is a daily reward issued according to your ranking and the group you belong to.|The reward is different depending on the ranking.|You can collect the rewards by clicking The treasure chest in the upper right corner.|The treasure chest will be refreshed every day at 22:00(GMT+8). Please note that the reward content will be settled according to your yesterday's 22:00 ranking.|* Final reward:|The final big reward will be issued according to your ranking and the group you belong to.|The reward is sent by email!|* Top Title reward:|a special title only owned by the Top.10 group A player!|The title reward will be issued within 7 working days via mailbox!||About the Champion League points:| (1) Each member participating in the competition will have an initial point of 2000.| (2) Points can be increased or decreased in the following ways.| * attack success- ↑/ Defense success- ↑| * attack failure- ↓ / defense failure- ↓|(3) If your level is upgraded to the new group, you will restart the game.||About the selection of Champion League promotion:|When the new group is promoted, the system will give you a chance to choose.| * Select A. Keep the previous group.|Final Reward: issued according to previous group/ Daily reward: issued according to the current group.| * Select B. Don't keep the previous group.|Final Reward: issued according to current group/ Daily reward: issued according to current group.| * Regardless of whether you choose to keep your group or not, when you upgrade the group, your points will be reset to initial points.| * After promotion, players in the previous group will not be able to attack you.| * 100 level users do not have the problem of promotion.| * If you don't make a choice before the Champion League over,It will keep the previous group|| About Champion League battle:|(1) Challenge opponent's range: -10 Your Rank Num +10|(2) Protection measures: After the defender is attacked, there are certain protection measures. After the measures are activated, It will continue for a period of time and other users will not be able to attack.|(3) Fanatic Mode: Daily 21: 00-22: 00 (GMT+8) is a weak protection measure, and the protection duration is shortened to 3-min.|(4) The team ’s Abilities: The remaining combat capabilities are calculated based on the actual situation of your development.|| About the Honor Room of the Champion League:| * The Honor Room is temporarily closed for the first competition.| * The Honor Room can view previous champions.|"
		},
