		},
		{
			"ELEMENT_EQUIP_RULE_TEXT",
			"Conditions for wearing Elemental Gear: Academy Level 100, Non-Vows Girl with red + 1 quality full gear (excluding Awakening and Blood Awakening gear), Vows Girl has full level 20 gear and/or above. | 2. Elemental gear has three element attributes: thunder, fire, and water. | 3. Elemental gear can be divided in general gear or special gear. There are special gear, which can only be equipped by a specific Girl. | 4. After wearing Elemental Gear, the attributes of the elements that are the same as those of the Elemental Gear can be obtained. | 5. Element attributes affect other element attributes. When a Girl with one element attribute attacks a Girl with another element attribute, the attacker gets a special bonus. | 6. Elemental Gear benefits a Girl once she wears it. Elemental Gear can be dismantled, but cannot be equipped by other Girls. | 7. Additional attributes can be obtained when elemental gear is enhanced. If the attributes of common gear are consistent with attributes of elemental gear, the girl gains additional benefits for wearing common gear. | 8. Once an elemental gear is dismantled, a certain amount of materials are returned. || Relationship each Elementals: | Thunder  Water: Reduce 30 Energy Points (1 seconds Cool down) | Water  Fire: 8% Damage of target's current HP when attacking | Fire  Thunder: Reduce target's attack speed by 40% when attacking | Any Elemental Attributes  No Elemental Attribute: Increase damage by 8% when attacking."
