			"1、所有戰姬都可以參與鍛造，將依據戰姬的武力、靈巧、法術值提供對應的收益。|2、最多可派遣5名戰姬參與鍛造，鍛造期間可以隨時調整鍛造戰姬。|3、戰姬們的總武力值越高，您獲得的道具集點（僅限鍛造的道具）越多；戰姬們的總靈巧值越高，您鍛造道具的時間加速效果越強；戰姬們的總法術值越高，您獲得的魔法石集點數量區間越高。|4、戰姬們鍛造道具時需要集中精力，因此參與鍛造的戰姬無法參與打工大作戰、公告板任務以及被租借。|5、如果您需要派遣參與鍛造的戰姬進行其他任務，那麼請先將她們從鍛造坊召回喲！"
