		{
			"FLAPPY_BIRD_RULE_TITLE",
			"Miracle Flight"
		},
		{
			"FLAPPY_BIRD_RULE_TEXT",
			"Far away from the academy's landscape there is a site of a miracle. A shocking, unknown history is about to emerge. Control the girls by flying through many obstacles and find this ancient mystery!|1. In the game, click the blank space on the screen to have the girls fly up a short distance.|2. In the game, a girl dies when she touches the top or bottom of the screen. Girls start with certain amount of HP. Whenever your girls touch a column, she will lose HP. When her HP drops to zero, she dies.|3. In the game, click on the lower left corner to use a girl's skill. You can only choose Angel at the beginning. Unlock girls with more powerful skills by playing a certain times of the game or spending diamonds. Every girl has their own advantages. Make good use of their advantages to play well.|4. You have a certain number of free daily challenges. You can receive additional challenges by spending stamina. The total game score will be converted into score points by a proportionate number. Corresponding rewards can be obtained in the Exchange Interface (Advanced rewards will be unlocked once you receive a score). The highest points will be ranked in the whole service. Players who are ranked high enough receives exclusive titles and rewards after the event is over. Please check your email.|5. The task will be refreshed at 5:00 a.m. daily in the Exchange Interface. Once you completed the task, you can score a lot. Remember to complete the task every day.|6. You can play practice mode as many times as you want, but it won't count towards your score. Practice and earn a high score!"
		},
