		{
			"RAGNAROK_BOSS_RULE_TITLE_1",
			"Rules of Dusk of the Gods Event"
		},
		{
			"RAGNAROK_BOSS_RULE_TEXT_1",
			"1. Players who are level 10 or higher can participate in Dusk of the Gods event. |2. This event has four parts including the Story, Mission, Odin’s Reward, and Dusk of the Gods. |3. Once the Story is complete, the other three modes are unlocked. |4. In Mission, three tasks will refresh at 5:00 a.m. every day. Players will receive rewards after completing all missions. |5. In Odin’s Reward, you can use Loki’s balloon to get rewards, which are randomized. In addition, you can directly pay 100 diamonds to buy Loki’s balloon. |6. Opening the [Dusk of the Gods] challenge requires one Gjallar's Horn and 24 stamina. There are two ways to enter. |1) In team mode, three players are required to enter the team, and the position in the team determines the enemies one must fight against. It cannot be changed throughout the challenge. Position one must fight against Fenrir, who will receive additional bonus scores, while the other two positions fight against Loki, who will receive less bonus points. |2) In single mode, you can choose which enemy to fight against. The enemy is weaker in this mode than team mode. But there are no extra bonuses. |7. In the [Dusk of the Gods] challenge, all girls will level up.  The non-vows girls will level up to 100 red + 1 quality, and they will be equipped with full enchantment, full skill level, full awakening, and blood awakening. The vows girls will level up to 100, have full equipment level 30. Girl’s star level and the attribute promotion obtained through other channels will be reserved. |8. < Dusk of the Gods > challenge must be completed within few minutes. You win if you defeat Fenrir. Quitting the challenge or running out of time is an automatic defeat. The game will not consume Gjallar's Horn, but your stamina will not be returned. |9. The Dusk of the Gods have two ranking lists. The first ranking list is the Carry List, which is based on the Carry Score. The second ranking is the Ultimate List, which is based on highest score on a single challenge. Once the event is over, rank rewards will be sent to you by mail.The top 10 Carry player can get title reward 『Fenrir』|10. After event,『Loki's Balloon』『Golden Apple』『Gjallar's Horn』will expire, please use them in time."
		},
