		},
		{
			"RAGNAROK_BOSS_RULE_TITLE_2",
			"Dusk of the Gods Rules"
		},
		{
			"RAGNAROK_BOSS_RULE_TEXT_2",
			"1. To start the Dusk of the Gods, you need to consume 1 Gjallar's Horn and 24 stamina. There are two ways to enter. |1) In team mode, three people are required to enter the room, and the position in the team determines the enemies one will face. It cannot be changed during the challenge. One position must fight against Fenrir, who will receive additional bonus score, while the other two positions fight against Loki, who will receive less bonus score.|2) In single player mode, you can freely choose which enemy to fight against, and the strength of the enemy is weaker than team mode. But there are no extra bonus. |2. In the \"Dusk of the Gods\" challenge, all girls will level up. The non-vows girls will level up to 100 red + 1 quality, and they will be equipped with full enchantment, full skill level, full awakening, and blood awakening. The vows girls will level up to 100, have full equipment, etc. Girl’s star level and the attribute promotion obtained through other channels will be reserved for girls. |3. < Dusk of the Gods > the challenge will be completed within 10 minutes, and you can win if you defeat Fenrir. Quitting the challenge or running out of time will lead to defeat. The game will not consume the Gjallar's Horn, but the 24 stamina will not be returned. Exit halfway the battle you won't get any golden apple. |4. The Dusk of the Gods have two ranking list. The first ranking list is the Carry List, which counts the Carry Score. The second ranking list is the Ultimate List, which counts the highest points of a single challenge. You will receive additional ranking rewards after the end of event, these rewards will be sent in 7 working days~"
		},
