		{
			"ACTIVITY_VIP_BOX_DRAW2_TEXT",
			"1.Masters can use Game Ticket to open those chests. Game Ticket can be obtained from events. Game Ticket won't be expired after the event ends.|2.There are 3 types of chests. Golden Chest is available to all players, Platinum Chest is available to vip5&above players while the Diamond Chest is available to players who are vip9&above. Each chest contains a random girl, click the magnifier to view girls you can possibly get from each chest.|3.All Chests contain girls that have been released in game while VIP9 chest additionally contains a rate-up SX girl.|4.VIP5&VIP9 chests contain an extra magic card which randomly displays numbers from 0 to 5. When the number is not 0, masters can get amount of scrolls of the girl you get this time that equals to 2*(the number on magic card) as bonus."
		},
