			"ACTIVITY_BALLOON_RULE_TITLE",
			"Summer Balloon Rule"
		},
		{
			"ACTIVITY_BALLOON_RULE_TEXT",
			"Welcome to the Summer Balloon Event! |1. Each round of rewards consists of 16 balloons. Breaking the balloons can get a random item, and one of the 16 balloons must contain the highest reward for the current prize pool display. |2. The ordinary prize pool is blue balloons, the rare prize pool is purple balloons, and the Top prize pool is golden balloons. |3. There is a small probability of a rare prize pool when refreshing. Only in the 4th to 6th rounds there is a small probability to encounter the skin prize pool, and the skin prize pool will definitely be encountered within 6 rounds. |4. The skin prize pool will only appear once. When it appears, the refresh button will be locked and cannot be refreshed. |5. Use a small amount of diamonds to refresh the current prize pool. The daily refresh limit is 10 times. The first refresh is free. |6. Refresh when the highest reward of the current prize pool has not been obtained, and the current round will not be increased. |7. When you get the highest reward of this round, you will be given a free refresh opportunity, and will not occupy the number of daily refreshes. After this refresh, the current round will be +1.|8. The largest round of the prize pool of this event The number of times is 25, and it cannot be refreshed after reaching the upper limit of rounds. |9. Rewards of this event include: |Top prize pool:Fencer's skin Wonder Heroine*1 |Rare prize pool: Yuri's skin Night Fairy*1, Wandy's skin Chopping Summer*1, Nancy's skin Baseball Catcher*1|ordinary prize pool:Legend Purify*15, Classic Furniture Coupon*20, Purple Gear Pack*8, Brave Evidence Pack I*5, Victory Vow Pack*3, Vows Essence*3000."
		},
