		{
			"ACTIVITY_FISHING_RULE_TEXT",
			"1. Masters can use fishing hooks (equipment), fishing rods (equipment), and baits (consumables) to play fishing race. |2. Masters can catch different kinds of fish in the fishing game. These fish are divided into 6 kinds of rarities. |3. The probability of catching fish with different rarities is related to the quality of fishing tackle (hooks, rods) and baits. The higher the quality, the higher the probability of catching rare fish~|4. The fish you catch will be directly converted into different amounts of fishing coins and fishing exp.  |5. Fishing exp can increase the fishing level (up to 5), higher level can unlock more options of fishing shop~|6. Fishing coins can be used to buy hooks, rods, baits or other rewards in the fishing shop. Fishing coins will be cleared after the event ends. Master must redeem the rewards before the event ends. "
