		{
			"OBJECT_MAIN_RULE_TEXT",
			"1. Masters can open Elective after reaching LV90. |2. In Elective, masters can choose the corresponding subjects for girls. After finishing the subject, you can bind girl's skills and obtain the attribute bonus. |3. Elective needs related application, which can be obtained from Memoir and other events. |4. Each girl can only take 4 subjects at most. Each subject can only be bound with one skill, and each skill can only be bound to one subject. After binding, the binding can be released and the subject can be forgotten. |5. You can use the learning materials to increase the proficiency of the subject to obtain more attribute bonus. The AC Bookshop has free random learning materials every day, don't forget it~"
