			"MAGIC_LAB_RULE_TITLE",
			"Alchemy Instruction"
		},
		{
			"MAGIC_LAB_RULE",
			"1. If masters reach LV90, you can open the Alchemy. In the Alchemy, you can purify the exclusive awaken equipment of girls and pets. Only the awaken girls and pets can purify the exclusive equipment attribute. |2. The initial Strength, Int, Agility of the awaken girls' exclusive equipment are all 0. Every purify will increase or decrease Strength, Int, Agility. When a certain value is reached, the additional attribute bonus will be unlocked. |3. The purify methods include Legendary Purify, Advanced Purify and Ordinary Purify. Legendary Purify and Advanced Purify consume diamonds. Ordinary Purify consumes coins. Purify results could be positive or negative. Masters can also lock the purify attribute, but the amount of gold coins and diamonds consumed will increase and the Blessings will be consumed. The Blessings will be reset once a day. |4. In addition to diamonds and gold coins, masters can also choose to use purify ticket for purifying. Each purifying can ensure that each attribute increases a little. After purifying, masters need to click Save to save the data. |5. In the automatic purifying mode, masters can select the times and methods of purifying, click start purifying to carry out automatic purifying, and the purify results will be directly saved, regardless of whether the results are positive or negative."
		},
