		{
			"OCCLUT_RULE_TITLE",
			"Sorcery War  Rule"
		},
		{
			"OCCLUT_RULE_TEXT",
			"Rules for participating in the competition: | 1. The Sorcery War  consists of multiple independent chapters. |2. Each chapters requires a sufficient number of players to open. |3. Each player needs to consume one Sorcery Scroll to participate in the chapter. |4. The Sorcery Scroll can be obtained from daily stamina consuming, every 3000 stamina consuming will give you 1 Sorcery Scroll. |5. When the number of scrolls held by players reaches the maximum, the scrolls can't be accumulated. |6. There is no limit for the Fight Effectiveness of the team with players from the same server. Players with level difference less than five can join the cross server team. |7. Single player can select Single mode to open the challenge for getting Sorcery Scrolls in chapter. |8. The strength of enemies in Single mode is the same as that in Team mode, but players in Single mode will have more dispatch places. |9. The reward mechanism of Single mode is the same as that of Team mode. ||Fighting Rules in Chapter: | 1. Each chapter is composed of multiple strongholds. Strongholds are linked by paths. Each stronghold will have an array of enemies. The chapters not opened show gray and the chapters can be challenged are lighted. |2. The chapter maps have different buffs due to Boss feature. |3. Each group of enemies can be challenged by Single mode or Team mode. |4. Each group of enemies can only open one battle at a time | 5. Each group of enemies will have a 1 minute time limit for selecting girls. If it exceeds the time limit, players will withdraw from the current battle and select girls again. |6. After the end of the battle, the status of the girls and enemies sent by players will be saved, and the pets' energy will be recalculated at the beginning of the next battle. |7. Every time you send a girl who has not fighted, you will consume one dispatch place. After the place is exhausted, you can only dispatch those who have fighted. |8. When the remaining time of the chapter is less than 2.5 minutes, you can't open a new battle. |The Raid function of each chapter will be activated after a challenge. ||Reward rules in chapter: | 1. The reward after the challenge is determined according to points you got. The higher the points you got, the richer the reward. |2. The points is related to the degree of completion, every one percent of the completion in the chapter will make you obtain 10 points. |3. After the completion degree reaches 100%, all girls not killed, the dispatch places not consumed and the remaining time will be converted into points according to a certain proportion. |4. Players who fight in the same chapter will get the same points. |5. The reward of Raid is obtained according to a certain proportion of the highest points in the challenge history of this chapter."
		},
