		{
			"FIFTH_ANNI_GACHA_RULE_TITLE",
			"Ceremony Capsule Rule"
		},
		{
			"FIFTH_ANNI_GACHA_RULE_TEXT",
			"1. There are four reward pools in the Ceremony Capsule, three of which are optional and the last is ordinary. 2. In the optional pool, masters can select the prize you want in the prize list and put into the prize pool and lock it. 3. When all the rewards of the optional prize pool are selected, masters can lock the prize pool of Capsule. |4. After prize pool of Capsule is locked, masters' prize pool of capsule is composed of \"All selected rewards in optional rewards pool\" and \"Rewards in ordinary prize pool\". | 4. Only after the reward pool of Capsule is locked, masters can draw the reward. | 5. Masters can use Reset Capsule Coin to reset the Capsule, the Reset Capsule Coin can be obtained in other events. | 6. Masters can use Ceremony Capsule Coins to draw reward from Ceremony Capsule. |7. The coin can be purchased by spending diamonds or by recharging diamonds (Every 300 diamonds recharging will give you 1 coins, the recharge value of multiple orders can be accumulated)"
		},
