		{
			"FIFTH_ANNI_PARTY_RULE_TITLE",
			"The Paradise Party Rule"
		},
		{
			"FIFTH_ANNI_PARTY_RULE_TEXT",
			"1. Masters can get all kinds of party gifts in the Paradise Ceremony and other events. Among them: | Silk Ribbon and Mysterious Love Letter can be obtained from the Paradise Lord or other events; |Ceremony Chocolate and Ceremony Fireworks can be obtained in the Ceremony Capsule; | Ceremony Windmill and Ceremony ice cream can be obtained in Top Floor and 1on1; | Ceremony Soda and Ceremony Balloon can be obtained in Chapter and Elite Chapter| 2. Masters can give gifts to each other in Paradise Ceremony, and masters who give gifts can get the Friendship Points according to the gifts and masters who receive the gifts can get the Ceremony Points | 4. For the gifts making masters get first 500 Ceremony Points, the sender can get 20% extra Friendship Points bonus. | 5. Masters can send gift via 5 ways including Friends, Guild Friends, Search Player ID, Other masters system randomly recommends to you and Resend gift. | 6. If masters get gift for the first time (excluding the gifts received from other masters), you can unlock the corresponding picture in your Gift Guide. f you unlock all the gifts in Gift Guide, you can get extra rewards. | 7. The Ceremony Points can improve masters' Ceremony Level, and every 100 Ceremony Points can increase the Ceremony Level by 1 level. | 8. According to the Friendship Points and Ceremony Level of masters, masters can unlock and receive the Friendship Reward. | 9. According to masters' Ranking of the  Friendship Points accumulated in Academy, Academy will send you the Ranking Reward to masters via mail after the event ends."
		},
