		{
			"FIFTH_ANNI_BOSS_RULE_TITLE",
			"Paradise Lord Rule"
		},
		{
			"FIFTH_ANNI_BOSS_RULE_TEXT",
			"1. The Paradise Lord is coming! If you challenge the Paradise Lord, you can get Challenge Points and reduce the total HP of the Paradise Lord. 2. There are four kinds of Difficulties for the Paradise Lord. After having defeated the Lord with Difficulty 1, Difficulty 2 and Difficulty 3, it will automatically jump to the the next Difficulty and can't be reversed. But masters don't need to worry, the Challenge Points getting from challenging Lord with higher Difficulty are more than those from low Difficulty. At the same time, you will get extra reward after having beaten down the Lord with every Difficulty for the first time~ | 3. Every 25% decrease in the remaining total health of the Paradise Lord, the status of the Paradise Lord will also change~ Please pay attention to the Lord's status to challenge! |4. When the total life of the Paradise Lord drops to 0% or the event is over, the Academy will send the rewards to masters via mail according to the Lord's final life status. Please work together to defeat the Paradise Lord! |5. Masters' challenge chance for challenging the Lord will be refreshed to 5 times at 5:00 in the morning every day. If you use dias to buy the chance, please make sure that you have used the chances before the times been refreshed! |6. When the total life of the Paradise Lord drops to 0% or the event is over, the Academy will send the rankings rewards to masters via mail according to masters' ranking for Total Challenge points in the event. The chat bubble in the ranking reward can be used without time limit~ But please remember that the Challenge Points getting after the total life of the Paradise Lord drops to 0% will not count to your ranking!"
		},
		{
			"FIFTH_ANNI_MAIN_RULE_TITLE",
			"Paradise Ceremony Rule"
		},
		{
			"FIFTH_ANNI_MAIN_RULE_TEXT",
			"The 5th Anniversary Ceremony of the Academy is coming. Masters can enjoy yourselves and get all kinds of rewards in the Paradise~ |1. Ceremony Party|Masters can get a variety of party gifts in the Paradise Ceremony and other events and send gifts to other masters in the Party. Come to get more gifts! If you give gifts to different masters, you will get more rewards~ |2. Paradise Journey|You can get all kinds of surprises during the Paradise Journey~ |3. Ceremony Capsule| It is said that Academy has prepared a special Capsule in the Ceremony, masters can choose the rewards you want freely~ | 4. Paradise Lord|Our Paradise has a new friend-Finlil, who says that she will beat masters, looks a little familiar? Challenge Finlil and get rich rewards! If we can make concerted efforts to defeat Finlil, Academy will prepare extra rewards for all masters~"
		},
