		{
			"SPIRIT_RULE_TITLE",
			"Horcrux Rule"
		},
		{
			"SPIRIT_RULE_TEXT",
			"Horcrux: | 1. Girls can gain attribute and fight bonus after wearing Horcrux. | 2. Each girl has 6 Horcrux position, which can be equipped with corresponding Horcrux. | 3. Different Horcruxes provide different attributes, and the higher the quality and level of Horcruxes, the more the attributes it provide. | 4. Each Horcrux has one main attribute and several additional attributes. The higher the quality of the Horcrux, the more additional attributes it may have. |5. Every girl must equip the suitable Horcrux then she can fully use her strength~ ||Horcrux Main Attribute: |The main attributes of Horcruxes in different positions are as following|1. Position 1: Attack, Spell Power| 2. Position 2: Horcrux Attack bonus, Horcrux HP bonus, Crit Rate, Effect Hit | 3. Position 3: Physical Def, Spell Resist. | 4. Position 4: Horcrux Attack bonus, Horcrux HP bonus, Horcrux Def bonus, Crit DMG, Effect Resist. | 5. Position 5: MAX HP| 6. Position 6: Horcrux Def bonus, Crit Rate, Effect Hit, Effect Resist. | Horcrux suit: | 1. Horcruxes with the same name on different positions make a suit(even if the quality of these Horcruxes are different) | 2. When the number of Horcruxes in the same suit equipped reaches 2 pieces /4 pieces, it can activate the Horcrux suit effect and provide additional attributes or special skills. ||Horcrux Enhancement: | 1. Enhancing Horcrux needs to consume other Horcruxes and coins. | 2. Horcrux level can be increased by enhancing. | 3. The higher the level, the higher the main attribute improved by the Horcrux. | 4. When the level of Horcrux is increased to 3, 6, 9, 12 and 15, you can improve the existing additional attributes or get a new additional attribute. ||Others: | 1. Horcruxes can be obtained from Evaluation-Gods Trial. Each Horcrux will generate its own unique attributes after obtaining. | 2. Horcrux attack bonus, Horcrux HP bonus and Horcrux Def bonus only increase the related attributes provided by all the Horcruxes the girl equipped (【Attack and Spell Power】, 【MAX HP】, 【Physical Def and Spell Resist】)|3. Effect hit rate's increase can make girl's specific negative state easier to hit; As the same, Effect resist increasing can make girls harder to be hit by negative state.|4. The specific negative state can be affected by Effect hit and Effect resist are following: Silent, Blind, Stunned, Heal Decrease, Seduced, Changed, Exiled, Frozen, Petrifacted, Catched, Horror, MP Restricted, Cursed, Fixed, Slept (Some additionally activated negative state will not be influenced)"
		},
		{
			"SPIRIT_CAMPAIN_RULE_TITLE",
			"Gods Trial Rule"
		},
		{
			"SPIRIT_CAMPAIN_RULE_TEXT",
			"1. Masters can challenge the Gods Trial after reaching LV60. After passing it you can obtain related Horcruxes |2. The trial takes a week as a cycle to circulate, everyday's trial is different. | 3. Each trial needs to pass the previous level to unlock the next level, and different levels have open level restrictions. | 4. Challenge any trial needs 20 LP, and LP will recover 1 point naturally every 6 minutes. The MAX is 180. | 5. After passing a certain trial, you can use auto mode to challenge this trial, and you can get rewards after some time after you choose auto mode(The reward is the same as the manual mode) | 6. The difficulty of all trials will gradually decrease with the extension of the battle time. Come on, masters ~ | 7. The types of Horcruxes dropped in the trial from Monday to Sunday are different, you can refer to following chart(The item only shows the highest quality Horcrux it will drop):"
		},
